    "encoding/json"
    "strings"
    "os"
)

func yamlToJSON(yamlStr string) (string, error) {
    var data interface{}
    dec := yaml.NewDecoder(strings.NewReader(yamlStr))
    // need to handle multiple docs? try single
    if err := dec.Decode(&data); err != nil {
        return "", err
    }
    // convert via json marshal with use number?
    j, err := json.Marshal(data)
    return string(j), err
}

func jsonToYaml(jsonStr string) (string, error) {
    var data interface{}
    if err := json.Unmarshal([]byte(jsonStr), &data); err != nil {
        return "", err
    }
    var buf bytes.Buffer
    enc := yaml.NewEncoder(&buf)
    enc.SetIndent(2)
    if err := enc.Encode(data); err != nil {
        return "", err
    }
    enc.Close()
    return buf.String(), nil
}

func main() {
    tests := []string{"a: 1\n", "a: [1, 2, 3]\n", "a: hello\n", "a: true\n", "a: null\n", "a: 1\n---\nb: 2\n"}
