        j, err := yamlToJSON(t)
        fmt.Printf("YAML %q -> JSON %q err %v\n", t, j, err)
        if err == nil {
            y, err2 := jsonToYaml(j)
            fmt.Printf("  JSON -> YAML %q err %v\n", y, err2)
        }
        _ = os.Stderr
    }
}
