    var buf bytes.Buffer
    for i, js := range jsonStrs {
        if i > 0 {
            buf.WriteString("---\n")
        }
        var data interface{}
        json.Unmarshal([]byte(js), &data)
        enc := yaml.NewEncoder(&buf)
        enc.SetIndent(indent)
        enc.Encode(data)
        enc.Close()
        // yaml encoder adds "---"? Need to handle
    }
    return buf.String(), nil
}

