package main

import (
    "bytes"
    "encoding/json"
    "fmt"
    "os/exec"
    "strings"
)

func runJq(filter string, jsonInput string) (string, error) {
    cmd := exec.Command("jq", filter)
    cmd.Stdin = strings.NewReader(jsonInput)
    var out bytes.Buffer
    var errBuf bytes.Buffer
    cmd.Stdout = &out
    cmd.Stderr = &errBuf
    err := cmd.Run()
    if err != nil {
        return "", fmt.Errorf("jq error: %s: %v", errBuf.String(), err)
    }
    return strings.TrimSpace(out.String()), nil
}

func main() {
    tests := []struct{ filter, input string }{
        {".a", `{"a": 1, "b": 2}`},
        {".a = 2", `{"a": 1}`},
        {".a[]", `{"a": [1,2,3]}`},
        {"select(.a == 1)", `{"a": 1}`},
        {"select(.a == 2)", `{"a": 1}`},
        {".", `{"a": 1}`},
        {".x = 1 | .y = 2", `{"a": 1}`},
        {".a + 1", `{"a": 1}`},
        {"[.a[] | select(. == 2)]", `{"a": [1,2,3]}`},
    }
    for _, t := range tests {
        out, err := runJq(t.filter, t.input)
        fmt.Printf("filter %q input %q -> %q err %v\n", t.filter, t.input, out, err)
    }
}
