package main

import (
    "bytes"
    "encoding/json"
    "fmt"
    "gopkg.in/yaml.v3"
    "os/exec"
    "strings"
)

func yamlDocsToJsonSeq(yamlStr string) ([]json.RawMessage, error) {
    dec := yaml.NewDecoder(strings.NewReader(yamlStr))
    var docs []json.RawMessage
    for {
        var data interface{}
        err := dec.Decode(&data)
        if err != nil {
            if err.Error() == "EOF" {
                break
            }
            return nil, err
        }
        j, _ := json.Marshal(data)
        docs = append(docs, json.RawMessage(j))
    }
    return docs, nil
}

func runJqOnDocs(filter string, docs []json.RawMessage) ([]string, error) {
    // jq expects newline separated JSON inputs when using multiple docs? Or we can feed as stream
    // Use jq -n or jq with multiple inputs
    // For eval (per doc), we run jq per doc
    // For eval-all, we need to load all docs and run once
    var results []string
    for _, doc := range docs {
        cmd := exec.Command("jq", filter)
        cmd.Stdin = bytes.NewReader(doc)
        var out bytes.Buffer
        var errBuf bytes.Buffer
        cmd.Stdout = &out
        cmd.Stderr = &errBuf
        err := cmd.Run()
        if err != nil {
            // check if jq error is about null? still return?
            // For our usage, empty output means no match
            if out.Len() == 0 {
                // could be filter produced no output (select false)
                // That's not error, just empty
                // But jq would exit 0?
                // Let's treat err with empty out as no result
                continue
            }
            return nil, fmt.Errorf("jq: %s", errBuf.String())
        }
        s := strings.TrimSpace(out.String())
        if s == "" || s == "null" {
            // need to capture null case for exit-status
            // For now include
        }
        // jq may output multiple lines for arrays like .a[] => each on new line
        // We need to capture all lines as separate results?
        // For yq, each result becomes a doc separator "---"
        lines := strings.Split(s, "\n")
        // But jq output for object is pretty printed with newlines, so splitting naively wrong
        // Better to use jq -c for compact?
        results = append(results, s)
    }
    return results, nil
}

func main() {
    yamlStr := "a: 1\nb: 2\n"
    docs, _ := yamlDocsToJsonSeq(yamlStr)
    fmt.Printf("docs %v\n", docs)
    res, _ := runJqOnDocs(".a", docs)
    fmt.Printf("res %v\n", res)
    // test array expansion
    yamlStr2 := "a: [1, 2, 3]\n"
    docs2, _ := yamlDocsToJsonSeq(yamlStr2)
    res2, _ := runJqOnDocs(".a[]", docs2)
    fmt.Printf("res2 %v\n", res2)
    // need to handle jq output that is not compact - better to run jq -c?
}
EOF
