    "fmt"
    "os/exec"
    "strings"
)

func main() {
    // Test jq handling of multiple outputs: .a[] produces stream, not array
    // When jq outputs multiple JSON values, they are whitespace separated, not array
    // yq should treat each as separate doc => "---" separator
    cmd := exec.Command("jq", "-c", ".a[]")
    cmd.Stdin = strings.NewReader(`{"a":[1,2,3]}`)
    var out bytes.Buffer
    cmd.Stdout = &out
    cmd.Run()
    fmt.Printf("jq -c .a[] -> %q\n", out.String())
    // lines: 1\n2\n3\n
    // When converted back to yaml with unwrap, each line "1" => yaml scalar unwrapped "1"
    // But when yq outputs multiple scalar results, it does: 1\n---\n2\n---\n3 ?

    // Check yq original for array
    outs, _ := exec.Command("./executable", ".a[]").CombinedOutput()
    // need to capture via shell
}
EOF
