package main

import (
    "bytes"
    "fmt"
    "gopkg.in/yaml.v3"
    "encoding/json"
)

func main() {
    // test encoding
    var data interface{}
    json.Unmarshal([]byte(`{"a":[1,2,3]}`), &data)
    var buf bytes.Buffer
    enc := yaml.NewEncoder(&buf)
    enc.SetIndent(2)
    enc.Encode(data)
    fmt.Printf("yaml %q\n", buf.String())
    fmt.Printf("cat -A: %s", buf.String())

    // second: pretty print vs normal
    // Normal yq outputs flow style for small arrays? a: [1, 2, 3] vs block
    // Check original: echo 'a: [1,2,3]' | yq '.' => "a: [1, 2, 3]" (flow)
    // While json->yaml produces block: a:\n  - 1\n...
    // So yq preserves style? How does it handle?
    // yq uses yaml Node with styles, not generic interface
    // With gopkg.in/yaml.v3 Decode into Node, preserve style?
    yamlStr := "a: [1, 2, 3]\n"
    var node yaml.Node
    yaml.Unmarshal([]byte(yamlStr), &node)
    fmt.Printf("node kind %d tag %s style %d content len %d\n", node.Kind, node.Tag, node.Style, len(node.Content))
    if len(node.Content) > 0 {
        doc := node.Content[0]
        fmt.Printf("doc kind %d tag %s\n", doc.Kind, doc.Tag)
        for i, c := range doc.Content {
            fmt.Printf("  c%d kind %d tag %s value %q style %d\n", i, c.Kind, c.Tag, c.Value, c.Style)
            if c.Kind == 4 { // mapping?
                for j, cc := range c.Content {
                    fmt.Printf("    cc%d kind %d tag %s value %q style %d\n", j, cc.Kind, cc.Tag, cc.Value, cc.Style)
                }
            }
        }
    }
    // Try encode node directly
    var buf2 bytes.Buffer
    enc2 := yaml.NewEncoder(&buf2)
    enc2.SetIndent(2)
    enc2.Encode(&node)
    fmt.Printf("node encode %q\n", buf2.String())
}
