    // Test flow style for sequences: 32?
    // Let's brute style for seq
    var node yaml.Node
    node.Kind = yaml.DocumentNode
    var mapNode yaml.Node
    mapNode.Kind = yaml.MappingNode
    mapNode.Tag = "!!map"
    var key yaml.Node
    key.Kind = yaml.ScalarNode; key.Tag = "!!str"; key.Value = "a"
    var seq yaml.Node
    seq.Kind = yaml.SequenceNode; seq.Tag = "!!seq"
