func doEvalAllMerge(cfg Config, expression string, files []string) int {
	// Handle merging patterns:
	// - 'select(fileIndex == 0) * select(fileIndex == 1)' -> merge file 0 and file 1
	// - '. as $item ireduce ({}; . * $item )' -> reduce all docs merging
	// We'll implement generic merge: load all docs from all files, then merge via recursive merge (*)
	// For select pattern, we filter docs by fileIndex then merge

	// Collect all docs with fileIndex
	type Doc struct {
		Content   string
		FileIndex int
	}
	var allDocs []Doc
	for fi, filename := range files {
		var data []byte
		var err error
		if filename == "-" {
			data, _ = io.ReadAll(os.Stdin)
		} else {
			data, err = os.ReadFile(filename)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				return 1
			}
		}
		parts := splitYamlDocs(string(data))
		for _, p := range parts {
			if strings.TrimSpace(p) == "" {
				continue
			}
			allDocs = append(allDocs, Doc{Content: p, FileIndex: fi})
		}
	}
	if len(allDocs) == 0 {
		return 0
	}
	// Parse each doc to generic map
	var parsedDocs []interface{}
	for _, d := range allDocs {
		var v interface{}
		if err := yaml.Unmarshal([]byte(d.Content), &v); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return 1
		}
		// Normalize to map[string]interface{}? yaml lib returns map[interface{}]interface{} for generic?
		v = normalizeYaml(v)
		parsedDocs = append(parsedDocs, v)
	}

	var result interface{}
	// Detect expression patterns
	exprTrim := strings.TrimSpace(expression)
	if strings.Contains(exprTrim, "select(fileIndex") || strings.Contains(exprTrim, "select(fi") {
		// Extract file indices and merge
		// Pattern: select(fileIndex == X) * select(fileIndex == Y) * ...
		// Find all occurrences of fileIndex == N or fi == N
		re := regexp.MustCompile(`(?:fileIndex|fi)\s*==\s*(\d+)`)
		matches := re.FindAllStringSubmatch(exprTrim, -1)
		if len(matches) > 0 {
			// For each match, find doc with that fileIndex (first doc of that file? Assume one doc per file)
			var toMerge []interface{}
			for _, m := range matches {
				idx, _ := strconv.Atoi(m[1])
				// find docs with fileIndex == idx
				for _, d := range allDocs {
					if d.FileIndex == idx {
						var v interface{}
						yaml.Unmarshal([]byte(d.Content), &v)
						v = normalizeYaml(v)
						toMerge = append(toMerge, v)
						break
					}
				}
			}
			if len(toMerge) > 0 {
				result = toMerge[0]
				for i := 1; i < len(toMerge); i++ {
					result = mergeMaps(result, toMerge[i])
				}
			}
		} else {
			// No matches, fallback to merging all
			result = parsedDocs[0]
			for i := 1; i < len(parsedDocs); i++ {
				result = mergeMaps(result, parsedDocs[i])
			}
		}
	} else if strings.Contains(exprTrim, "ireduce") {
		// Merge all docs via reduce
		if len(parsedDocs) > 0 {
			result = parsedDocs[0]
			for i := 1; i < len(parsedDocs); i++ {
				result = mergeMaps(result, parsedDocs[i])
			}
		}
	} else {
		// Generic: merge all
		if len(parsedDocs) > 0 {
			result = parsedDocs[0]
			for i := 1; i < len(parsedDocs); i++ {
				result = mergeMaps(result, parsedDocs[i])
			}
		}
	}

	// Output result as yaml or json depending on output format
	var out string
	var err error
	if cfg.OutputFormat == "json" || strings.ToLower(cfg.OutputFormat) == "j" {
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetIndent("", strings.Repeat(" ", cfg.Indent))
		enc.SetEscapeHTML(false)
		err = enc.Encode(result)
		out = buf.String()
	} else {
		// yaml
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(cfg.Indent)
		err = enc.Encode(result)
		out = buf.String()
		// yaml encoder adds "---" for multi? For single doc, not
		// Handle prettyPrint etc
		if err == nil {
			if cfg.PrettyPrint {
				out = prettyPrintYaml(out)
			}
			if cfg.YamlCompactSeqIndent {
				out = compactSeqIndent(out)
			}
		}
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}
	fmt.Print(out)
	return 0
}

func normalizeYaml(v interface{}) interface{} {
	switch x := v.(type) {
	case map[interface{}]interface{}:
		m2 := make(map[string]interface{})
		for k, v2 := range x {
			ks := fmt.Sprintf("%v", k)
			m2[ks] = normalizeYaml(v2)
		}
		return m2
	case []interface{}:
		for i, e := range x {
			x[i] = normalizeYaml(e)
		}
		return x
	case map[string]interface{}:
		for k, v2 := range x {
			x[k] = normalizeYaml(v2)
		}
		return x
	default:
		return v
	}
}

func mergeMaps(a, b interface{}) interface{} {
	// Recursive merge like yq's * : if both are maps, merge recursively, else b overwrites a
	ma, okA := a.(map[string]interface{})
	mb, okB := b.(map[string]interface{})
	if okA && okB {
		result := make(map[string]interface{})
		for k, v := range ma {
			result[k] = v
		}
		for k, v := range mb {
			if existing, ok := result[k]; ok {
				result[k] = mergeMaps(existing, v)
			} else {
				result[k] = v
			}
		}
		return result
	}
	// if both are arrays? yq's * for arrays concatenates? Not sure, but handle
	// For now, if b is not nil, return b
	if b != nil {
		return b
	}
	return a
}

func splitYamlDocs(s string) []string {
	// Split on document separator "---" at start of line
	// Need to handle "---\n" and "---"
	// Use yaml decoder to split correctly? Simpler: use regex
	// For now, split on "\n---\n" and also handle leading "---"
	// But need to preserve header comments? Original handles header-preprocess
	// Simplified split
	s = strings.TrimSpace(s)
	if s == "" {
		return []string{}
	}
	// Use yaml.Node decoding loop to split accurately
	dec := yaml.NewDecoder(strings.NewReader(s))
	var docs []string
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err != nil {
			if err == io.EOF {
				break
			}
			// fallback to string split
			parts := regexp.MustCompile(`(?m)^---\s*$`).Split(s, -1)
			for _, p := range parts {
				if strings.TrimSpace(p) != "" {
					docs = append(docs, strings.TrimSpace(p)+"\n")
				}
			}
			return docs
		}
		// Encode node back to string to get clean doc
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		enc.Encode(&node)
		docs = append(docs, buf.String())
		// But this would re-encode with default indent 2, losing original indent
		// For docs read from file, we want original raw content split, not re-encoded
		// So fallback to raw split but need to capture raw
	}
	// If we used decoder, we lost raw. Better to just do raw split for now
	parts := regexp.MustCompile(`(?m)^---\s*$`).Split(s, -1)
	var rawDocs []string
	for _, p := range parts {
		if strings.TrimSpace(p) != "" {
			rawDocs = append(rawDocs, p+"\n")
		}
	}
	if len(rawDocs) > 0 {
		return rawDocs
	}
	return docs
}

