func evaluateExpression(cfg Config, expression string, docContent string, docInfo Doc) (string, bool, error) {
	// Handle debug already
	// Validate expression first
	if err := validateExpression(expression); err != nil {
		return "", false, err
	}

	// Special handling for string interpolation disable
	if !cfg.StringInterpolation && strings.Contains(expression, "\\(") {
		// If disabled, treat "\(exp)" as literal
		// yq with --string-interpolation=false would output literal string "\(.a)" => but our test showed it outputs "\(.a)" ?
		// Actually echo 'a: 1' | yq --string-interpolation=false '"\(.a)"' gave literal "\(.a)"? Let's check original: it gave "\(.a)"
		// So we should return literal without interpolation
		// For now, if expression contains "\(" and interpolation false, just output the expression string content without evaluating inner?
		// Simplified: return the expression's quoted content without processing
		// Expression '"\(.a)"' when interpolation false should output string "\(.a)" unwrapped? But original gave "\(.a)" (with escaping)?
		// We'll just return the raw string without quotes if unwrap
		trim := strings.Trim(expression, `"`)
		trim = strings.Trim(trim, `'`)
		if cfg.UnwrapScalar {
			return trim, false, nil
		}
		return fmt.Sprintf("%q", trim), false, nil
	}

	// Handle simple cases without jq for performance and style preservation
	if expression == "." {
		// identity - return docContent as is, but handle output format conversion
		return convertOutput(cfg, docContent, docInfo)
	}
	if isSimplePath(expression) {
		return evaluateSimplePath(cfg, expression, docContent)
	}
	// Handle assignment: ".a = 2" or ".a.b = \"hello\"" etc
	if strings.Contains(expression, "=") && !strings.Contains(expression, "==") && !strings.Contains(expression, "!=") && !strings.Contains(expression, "=~") {
		return evaluateAssignment(cfg, expression, docContent)
	}
	// Handle pipe and other jq expressions: use jq

	// Preprocess yq-specific functions
	expr := expression
	// Handle strenv
	if strings.Contains(expr, "strenv") {
		if cfg.SecurityDisableEnvOps {
			return "", false, fmt.Errorf("env operations have been disabled")
		}
		expr = translateStrenv(expr)
	}
	if strings.Contains(expr, "env(") && cfg.SecurityDisableEnvOps {
		return "", false, fmt.Errorf("env operations have been disabled")
	}
	if strings.Contains(expr, "load(") {
		if cfg.SecurityDisableFileOps {
			return "", false, fmt.Errorf("file operations have been disabled")
		}
		// Handle load via replacement
		re := regexp.MustCompile(`load\("([^"]+)"\)`)
		matches := re.FindAllStringSubmatch(expr, -1)
		for _, m := range matches {
			filename := m[1]
			data, err := os.ReadFile(filename)
			if err != nil {
				return "", false, fmt.Errorf("bad file '%s': %v", filename, err)
			}
			var v interface{}
			if err := yaml.Unmarshal(data, &v); err != nil {
				return "", false, err
			}
			v = normalizeYaml(v)
			b, _ := json.Marshal(v)
			expr = strings.ReplaceAll(expr, m[0], string(b))
		}
	}
	// Handle string interpolation for yq: already jq supports similar, but yq's \(exp) inside strings is like jq
	// jq also supports that, so no need to translate

	// Convert yaml doc to json
	jsonStr, err := yamlToJson(docContent, cfg.InputFormat)
	if err != nil {
		// If input is not yaml? Try to handle empty?
		if strings.TrimSpace(docContent) == "" {
			jsonStr = "null"
		} else {
			return "", false, fmt.Errorf("bad file '-': %v", err)
		}
	}
	if jsonStr == "" {
		jsonStr = "null"
	}
	// Run jq
	// Need to handle $index, $fileIndex etc? For eval, those variables may be used but we don't support; if present, handle via eval-all path
	// For now, just run jq
	cmd := exec.Command("jq", expr)
	cmd.Stdin = strings.NewReader(jsonStr)
	cmd.Env = os.Environ()
	var outBuf bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	err = cmd.Run()
	if err != nil {
		// Check if jq output is empty and error is about no input? For select returning false, jq exits 0 with empty
		// But for error like "foo", jq returns error
		errStr := strings.TrimSpace(errBuf.String())
		if errStr == "" {
			errStr = err.Error()
		}
		// Map jq errors to yq errors? Original errors like "Error: foo" for 'error("foo")'
		// yq's error() function produces "Error: foo"
		// jq's error() produces "jq: error (at <stdin>:1): foo"
		// We should extract message
		if strings.Contains(errStr, "error") {
			// try to extract foo
			re := regexp.MustCompile(`error.*?:\s*(.+)`)
			m := re.FindStringSubmatch(errStr)
			if len(m) > 1 {
				return "", false, fmt.Errorf("%s", strings.Trim(m[1], `"`))
			}
		}
		return "", false, fmt.Errorf("%s", errStr)
	}
	outStr := strings.TrimSpace(outBuf.String())
	if outStr == "" {
		// select returned no match -> indicate no output
		return "", false, nil
	}
	// jq may output multiple JSON values separated by newline (for .a[] etc)
	// For yq, each output should be separate doc: we need to handle that our caller expects single result per doc, but if jq produced multiple, we should join with "---" or return as multiple?
	// Our current per-doc loop expects single output per doc, but .a[] produces multiple lines like "1\n2\n3"
	// yq outputs each as separate line without "---" when unwrap? Let's check original: echo 'a: [1,2,3]' | yq '.a[]' gave "1\n2\n3\n" (no "---")
	// While multi-doc with "---" is for multiple docs: e.g., two docs each with . output gives "a:1\n---\nb:2\n"
	// For array expansion, it's not docs but stream of values, yq outputs each value without separator? Actually test showed "1\n2\n3\n" with no "---"
	// But if we use -N false, then docs separator is "---", but for stream values, still no separator? Let's assume stream values are joined by "\n" (original does \n)
	// So for per-doc, if jq output contains multiple json values (like "1\n2\n3"), we should treat as single output with newline joining (no "---")
	// Our caller will then handle joining outputs with "---" between docs, but stream values within doc should already be newline separated without "---"
	// So we can just return outStr as is, and caller will treat it as one output string
	// But when output is json/yaml object, outStr will be pretty printed with newlines internal, but that's part of one object, not multiple
	// How to distinguish? jq -c would give compact per value without internal newlines, but we use default (pretty)
	// jq default for object is pretty with newlines, but for multiple values it would be multiple pretty objects separated by newline: "{\n  \"a\":1\n}\n{\n  \"b\":2\n}" ?
	// That's ambiguous
	// To avoid, we can use jq -c for per-doc? Then we can parse and reformat according to output format
	// Alternative: use jq -c and then convert back to yaml with our formatting

	// For now, we'll try to parse outStr as JSON stream
	// If output format is yaml and unwrapScalar true, we need to handle scalars unwrapped
	// Let's detect if outStr is multiple json values
	dec := json.NewDecoder(strings.NewReader(outBuf.String()))
	var results []string
	for {
		var v interface{}
		if err := dec.Decode(&v); err != nil {
			if err == io.EOF {
				break
			}
			// fallback to raw
			results = []string{outStr}
			break
		}
		// Encode v to output format
		var res string
		if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
			b, _ := json.MarshalIndent(v, "", strings.Repeat(" ", cfg.Indent))
			// json.MarshalIndent adds newline, we trim?
			res = string(b)
		} else {
			// yaml
			if v == nil {
				res = "null"
				if !cfg.UnwrapScalar {
					res = "null"
				}
			} else if s, ok := v.(string); ok && cfg.UnwrapScalar {
				// check if original yaml scalar style? For now unwrap
				// Also check NUL output check: if scalar contains NUL and NulOutput true, error
				if cfg.NulOutput && strings.Contains(s, "\x00") {
					return "", false, fmt.Errorf("nul output with NUL in scalar")
				}
				res = s
			} else if _, ok := v.(float64); ok && cfg.UnwrapScalar {
				// numbers unwrapped
				// Use json number formatting
				b, _ := json.Marshal(v)
				res = string(b)
			} else if b, ok := v.(bool); ok && cfg.UnwrapScalar {
				if b {
					res = "true"
				} else {
					res = "false"
				}
			} else {
				// complex
				var buf bytes.Buffer
				enc := yaml.NewEncoder(&buf)
				enc.SetIndent(cfg.Indent)
				enc.Encode(v)
				res = strings.TrimSpace(buf.String())
				if cfg.PrettyPrint {
					res = prettyPrintYaml(res)
				}
				if cfg.YamlCompactSeqIndent {
					res = compactSeqIndent(res)
				}
			}
		}
		results = append(results, res)
	}
	if len(results) == 0 {
		return "", false, nil
	}
	if len(results) == 1 {
		// Check for null/false for exit-status? Caller handles
		out := results[0]
		isNull := strings.TrimSpace(out) == "null" || strings.TrimSpace(out) == "false"
		// Also handle case where output was "null" but we want to return "null" string for printing?
		// Original prints "null" for ".b" missing, with exit-status errors
		// So we should return "null" for printing, but also indicate isNull for exit logic
		if isNull {
			return out, true, nil
		}
		return out, false, nil
	}
	// Multiple results from one doc (like .a[])
	// Join with "\n" without "---"
	joined := strings.Join(results, "\n")
	return joined, false, nil
}

type Doc struct {
	Content   []byte
	FileIndex int
	DocIndex  int
	Filename  string
}

func isSimplePath(expr string) bool {
	expr = strings.TrimSpace(expr)
	if expr == "." {
		return true
	}
	// reject if contains operators
	if strings.ContainsAny(expr, "=|*+(),\"'") {
		// But simple path could be .a.b with no operators, we already check
		// However path like .a.b[0] contains [ and ], but not in above charset? we excluded [ ] 
		// So check more
		if strings.Contains(expr, "=") || strings.Contains(expr, "|") || strings.Contains(expr, "*") || strings.Contains(expr, "+") || strings.Contains(expr, "(") || strings.Contains(expr, ")") || strings.Contains(expr, ",") {
			return false
		}
		if strings.Contains(expr, "\"") || strings.Contains(expr, "'") {
			return false
		}
	}
	if strings.Contains(expr, "select") || strings.Contains(expr, "load") || strings.Contains(expr, "strenv") || strings.Contains(expr, "env") {
		return false
	}
	if !strings.HasPrefix(expr, ".") {
		return false
	}
	// Check pattern: dot followed by word chars and brackets and dots
	re := regexp.MustCompile(`^\.(\w+(\[\d+\])?)?(\.\w+(\[\d+\])?)*$`)
	return re.MatchString(expr)
}

func evaluateSimplePath(cfg Config, expr string, docContent string) (string, bool, error) {
	// Parse yaml doc to Node
	var node yaml.Node
	if err := yaml.Unmarshal([]byte(docContent), &node); err != nil {
		// Try to handle empty
		if strings.TrimSpace(docContent) == "" {
			// empty doc -> treat as null
			return "null", true, nil
		}
		return "", false, err
	}
	// node is DocumentNode, content[0] is actual doc
	if len(node.Content) == 0 {
		return "null", true, nil
	}
	docNode := node.Content[0]

	// Special case "." returns whole doc
	if expr == "." {
		return convertOutputNode(cfg, docNode)
	}
	// Traverse path
	// Remove leading "."
	path := strings.TrimPrefix(expr, ".")
	parts := strings.Split(path, ".")
	current := docNode
	for _, part := range parts {
		if part == "" {
			continue
		}
		// Check for array index: e.g., "a[0]" or "a" without index
		re := regexp.MustCompile(`^(\w+)(?:\[(\d+)\])?$`)
		m := re.FindStringSubmatch(part)
		if m == nil {
			return "", false, fmt.Errorf("invalid path %s", part)
		}
		key := m[1]
		idxStr := m[2]

		// current should be MappingNode
		if current.Kind != yaml.MappingNode {
			// if trying to access field of non-map, return null
			return "null", true, nil
		}
		found := false
		var valueNode *yaml.Node
		for i := 0; i < len(current.Content); i += 2 {
			k := current.Content[i]
			v := current.Content[i+1]
			if k.Value == key {
				valueNode = v
				found = true
				break
			}
		}
		if !found {
			return "null", true, nil
		}
		current = valueNode
		if idxStr != "" {
			idx, _ := strconv.Atoi(idxStr)
			if current.Kind != yaml.SequenceNode {
				return "null", true, nil
			}
			if idx < 0 || idx >= len(current.Content) {
				return "null", true, nil
			}
			current = current.Content[idx]
		}
	}
	return convertOutputNode(cfg, current)
}

func evaluateAssignment(cfg Config, expr string, docContent string) (string, bool, error) {
	// Split on " = " (first occurrence)
	// Supports ".a = 2", ".a.b = \"hello\"", ".a = strenv(VAR)" etc
	parts := strings.SplitN(expr, "=", 2)
	if len(parts) != 2 {
		return "", false, fmt.Errorf("invalid assignment")
	}
	lhs := strings.TrimSpace(parts[0])
	rhs := strings.TrimSpace(parts[1])
	// Remove "|=" vs "="? Handle "|=" as update assignment, but treat as =
	if strings.HasSuffix(lhs, "|") {
		lhs = strings.TrimSuffix(lhs, "|")
		lhs = strings.TrimSpace(lhs)
	}
	// lhs should be simple path
	if !isSimplePath(lhs) {
		// fallback to jq
		return "", false, fmt.Errorf("fallback")
	}
	// rhs value: could be string literal, number, bool, null, or strenv, or path?
	// For now handle literals and strenv and simple paths
	var rhsNode yaml.Node
	rhsTrim := strings.TrimSpace(rhs)
	// Check for quoted string
	if (strings.HasPrefix(rhsTrim, `"`) && strings.HasSuffix(rhsTrim, `"`)) || (strings.HasPrefix(rhsTrim, `'`) && strings.HasSuffix(rhsTrim, `'`)) {
		val := strings.Trim(rhsTrim, `"`)
		val = strings.Trim(val, `'`)
		// handle escaped?
		rhsNode.Kind = yaml.ScalarNode
		rhsNode.Tag = "!!str"
		rhsNode.Value = val
		// preserve quotes? original's assignment with "cool" results in a: cool (unquoted) or "cool" depends on output
		// For simplicity use plain
		rhsNode.Style = 0
	} else if rhsTrim == "true" || rhsTrim == "false" {
		rhsNode.Kind = yaml.ScalarNode
		rhsNode.Tag = "!!bool"
		rhsNode.Value = rhsTrim
	} else if rhsTrim == "null" {
		rhsNode.Kind = yaml.ScalarNode
		rhsNode.Tag = "!!null"
		rhsNode.Value = "null"
	} else if rhsTrim == "[]" || rhsTrim == "{}" {
		// empty array/map
		if rhsTrim == "[]" {
			rhsNode.Kind = yaml.SequenceNode
			rhsNode.Tag = "!!seq"
			rhsNode.Style = yaml.FlowStyle
		} else {
			rhsNode.Kind = yaml.MappingNode
			rhsNode.Tag = "!!map"
			rhsNode.Style = yaml.FlowStyle
		}
	} else if strings.HasPrefix(rhsTrim, "strenv(") {
		if cfg.SecurityDisableEnvOps {
			return "", false, fmt.Errorf("env operations have been disabled")
		}
		re := regexp.MustCompile(`strenv\(([^)]+)\)`)
		m := re.FindStringSubmatch(rhsTrim)
		if len(m) > 1 {
			varName := strings.TrimSpace(m[1])
			varName = strings.Trim(varName, `"`)
			varName = strings.Trim(varName, `'`)
			val := os.Getenv(varName)
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!str"
			rhsNode.Value = val
		}
	} else if strings.HasPrefix(rhsTrim, "env(") {
		if cfg.SecurityDisableEnvOps {
			return "", false, fmt.Errorf("env operations have been disabled")
		}
		re := regexp.MustCompile(`env\(([^)]+)\)`)
		m := re.FindStringSubmatch(rhsTrim)
		if len(m) > 1 {
			varName := strings.TrimSpace(m[1])
			varName = strings.Trim(varName, `"`)
			varName = strings.Trim(varName, `'`)
			val := os.Getenv(varName)
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!str"
			rhsNode.Value = val
		}
	} else if isSimplePath(rhsTrim) {
		// rhs is path like .b.c ; need to fetch value from doc
		// For now fallback to jq for complex
		return "", false, fmt.Errorf("fallback to jq")
	} else {
		// Try to parse as number
		if _, err := strconv.Atoi(rhsTrim); err == nil {
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!int"
			rhsNode.Value = rhsTrim
		} else if _, err := strconv.ParseFloat(rhsTrim, 64); err == nil {
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!float"
			rhsNode.Value = rhsTrim
		} else {
			// fallback
			return "", false, fmt.Errorf("fallback")
		}
	}

	// Now we have doc to modify
	var docNode yaml.Node
	if err := yaml.Unmarshal([]byte(docContent), &docNode); err != nil {
		// if empty, create new document
		docNode.Kind = yaml.DocumentNode
		var mapNode yaml.Node
		mapNode.Kind = yaml.MappingNode
		mapNode.Tag = "!!map"
		docNode.Content = []*yaml.Node{&mapNode}
	}
	if len(docNode.Content) == 0 {
		var mapNode yaml.Node
		mapNode.Kind = yaml.MappingNode
		mapNode.Tag = "!!map"
		docNode.Content = []*yaml.Node{&mapNode}
	}
	target := docNode.Content[0]
	// If target is not mapping (e.g., scalar), need to replace?
	// For assignment .a = 2 on empty or null, create mapping

	// Traverse lhs path, creating intermediate nodes if needed
	path := strings.TrimPrefix(lhs, ".")
	parts := strings.Split(path, ".")
	current := target
	for i, part := range parts {
		re := regexp.MustCompile(`^(\w+)(?:\[(\d+)\])?$`)
		m := re.FindStringSubmatch(part)
		if m == nil {
			return "", false, fmt.Errorf("invalid path")
		}
		key := m[1]
		idxStr := m[2]
		isLast := i == len(parts)-1

		if current.Kind != yaml.MappingNode {
			// cannot create field on non-map, replace with map?
			// For simplicity, error
			return "", false, fmt.Errorf("cannot assign to non-map")
		}
		// Find key
		var foundIdx int = -1
		var valueNode *yaml.Node
		for idx := 0; idx < len(current.Content); idx += 2 {
			k := current.Content[idx]
			if k.Value == key {
				foundIdx = idx
				valueNode = current.Content[idx+1]
				break
			}
		}
		if isLast {
			if idxStr != "" {
				// assigning to array element: .a[0] = 2
				if foundIdx == -1 {
					// create array
					var seq yaml.Node
					seq.Kind = yaml.SequenceNode
					seq.Tag = "!!seq"
					// need to fill up to idx?
					idx, _ := strconv.Atoi(idxStr)
					// fill with nulls
					for j := 0; j <= idx; j++ {
						var nullNode yaml.Node
						nullNode.Kind = yaml.ScalarNode
						nullNode.Tag = "!!null"
						nullNode.Value = "null"
						if j == idx {
							nullNode = rhsNode
						}
						seq.Content = append(seq.Content, &nullNode)
					}
					// append to map
					var keyNode yaml.Node
					keyNode.Kind = yaml.ScalarNode
					keyNode.Tag = "!!str"
					keyNode.Value = key
					current.Content = append(current.Content, &keyNode, &seq)
				} else {
					// existing array, set element
					if valueNode.Kind != yaml.SequenceNode {
						return "", false, fmt.Errorf("not an array")
					}
					idx, _ := strconv.Atoi(idxStr)
					// expand if needed
					for len(valueNode.Content) <= idx {
						var nullNode yaml.Node
						nullNode.Kind = yaml.ScalarNode
						nullNode.Tag = "!!null"
						nullNode.Value = "null"
						valueNode.Content = append(valueNode.Content, &nullNode)
					}
					// replace
					// Need to allocate new node to avoid reference issues
					newNode := rhsNode
					valueNode.Content[idx] = &newNode
				}
			} else {
				if foundIdx == -1 {
					var keyNode yaml.Node
					keyNode.Kind = yaml.ScalarNode
					keyNode.Tag = "!!str"
					keyNode.Value = key
					// need to copy rhsNode
					newNode := rhsNode
					current.Content = append(current.Content, &keyNode, &newNode)
				} else {
					newNode := rhsNode
					current.Content[foundIdx+1] = &newNode
				}
			}
		} else {
			// intermediate node, need to traverse/create
			if foundIdx == -1 {
				// create new mapping
				var newMap yaml.Node
				newMap.Kind = yaml.MappingNode
				newMap.Tag = "!!map"
				var keyNode yaml.Node
				keyNode.Kind = yaml.ScalarNode
				keyNode.Tag = "!!str"
				keyNode.Value = key
				current.Content = append(current.Content, &keyNode, &newMap)
				current = &newMap
				// Note: we added to current.Content but current is pointer to original mapping's content; need to update reference
				// Actually we appended to current.Content slice, but current points to target's content mapping; after append, we need to find the newly added map
				// Since we just created newMap as value, we should set current to that map we can retrieve
				// Find last value
				current = current.Content[len(current.Content)-1]
			} else {
				// need to handle idxStr for intermediate array? e.g., .a[0].b
				if idxStr != "" {
					idx, _ := strconv.Atoi(idxStr)
					if valueNode.Kind != yaml.SequenceNode {
						return "", false, fmt.Errorf("not an array")
					}
					if idx >= len(valueNode.Content) {
						// create missing entries as maps?
						for len(valueNode.Content) <= idx {
							var newMap yaml.Node
							newMap.Kind = yaml.MappingNode
							newMap.Tag = "!!map"
							valueNode.Content = append(valueNode.Content, &newMap)
						}
					}
					current = valueNode.Content[idx]
					if current.Kind != yaml.MappingNode {
						// Convert scalar to mapping? For now error
					}
				} else {
					current = valueNode
					if current.Kind != yaml.MappingNode {
						// if intermediate is scalar, need to replace with map? But assignment would overwrite
						// Create new map and replace?
						var newMap yaml.Node
						newMap.Kind = yaml.MappingNode
						newMap.Tag = "!!map"
						current.Content = newMap.Content
						current.Kind = newMap.Kind
						current.Tag = newMap.Tag
					}
				}
			}
		}
	}
	// Encode back to yaml
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.Indent)
	if err := enc.Encode(&docNode); err != nil {
		return "", false, err
	}
	enc.Close()
	out := buf.String()
	// handle prettyPrint? For assignment, style already set, but prettyPrint clears style
	if cfg.PrettyPrint {
		out = prettyPrintYaml(out)
	}
	if cfg.YamlCompactSeqIndent {
		out = compactSeqIndent(out)
	}
	// For output format json, convert
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		var v interface{}
		yaml.Unmarshal([]byte(out), &v)
		v = normalizeYaml(v)
		b, _ := json.MarshalIndent(v, "", strings.Repeat(" ", cfg.Indent))
		out = string(b) + "\n"
	}
	// Handle unwrapScalar? For assignment, result is not scalar unwrap
	return strings.TrimSpace(out), false, nil
}

func convertOutput(cfg Config, docContent string, docInfo Doc) (string, bool, error) {
	// Convert docContent to output format with config
	// Handles input format vs output format
	// Simplify: assume yaml input already, output yaml/json etc
	input := strings.TrimSpace(docContent)
	if input == "" {
		return "null", true, nil
	}
	// Check input format
	if cfg.InputFormat == "json" || cfg.InputFormat == "j" {
		// input is json, but docContent is json string
		// Convert to output
		if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
			// pretty print json with indent
			var v interface{}
			json.Unmarshal([]byte(input), &v)
			b, _ := json.MarshalIndent(v, "", strings.Repeat(" ", cfg.Indent))
			return string(b), false, nil
		} else {
			// json to yaml
			var v interface{}
			json.Unmarshal([]byte(input), &v)
			var buf bytes.Buffer
			enc := yaml.NewEncoder(&buf)
			enc.SetIndent(cfg.Indent)
			enc.Encode(v)
			out := buf.String()
			if cfg.PrettyPrint {
				out = prettyPrintYaml(out)
			}
			return strings.TrimSpace(out), false, nil
		}
	}
	// default yaml input
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		var v interface{}
		if err := yaml.Unmarshal([]byte(input), &v); err != nil {
			return "", false, err
		}
		v = normalizeYaml(v)
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetIndent("", strings.Repeat(" ", cfg.Indent))
		enc.SetEscapeHTML(false)
		enc.Encode(v)
		return strings.TrimSpace(buf.String()), false, nil
	} else if cfg.OutputFormat == "props" || cfg.OutputFormat == "p" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toProps(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "csv" || cfg.OutputFormat == "c" {
		return "", false, fmt.Errorf("csv encoding only works for arrays, got: !!map")
		// Actually need to check v type
	} else if cfg.OutputFormat == "xml" || cfg.OutputFormat == "x" {
		// xml output: wrap?
		// Simplified: output as <a>...</a>
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toXml(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "shell" || cfg.OutputFormat == "s" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toShell(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "lua" || cfg.OutputFormat == "l" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toLua(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "ini" || cfg.OutputFormat == "i" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toIni(v)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "base64" {
		return "", false, fmt.Errorf("cannot encode !!map as base64, can only operate on strings")
	} else if cfg.OutputFormat == "uri" {
		return "", false, fmt.Errorf("cannot encode !!map as URI, can only operate on strings. Please first pipe through another encoding operator to convert the value to a string")
	} else if cfg.OutputFormat == "toml" {
		// stub
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		b, _ := json.Marshal(v)
		var m map[string]interface{}
		json.Unmarshal(b, &m)
		var sb strings.Builder
		for k, val := range m {
			switch vt := val.(type) {
			case string:
				sb.WriteString(fmt.Sprintf("%s = \"%s\"\n", k, vt))
			default:
				sb.WriteString(fmt.Sprintf("%s = %v\n", k, vt))
			}
		}
		return strings.TrimSpace(sb.String()), false, nil
	}
	// default yaml output
	// Need to handle yaml style, prettyPrint, etc
	var node yaml.Node
	if err := yaml.Unmarshal([]byte(input), &node); err != nil {
		// try to re-encode via generic if node fails?
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(cfg.Indent)
		enc.Encode(v)
		out := buf.String()
		if cfg.PrettyPrint {
			out = prettyPrintYaml(out)
		}
		return strings.TrimSpace(out), false, nil
	}
	if len(node.Content) == 0 {
		return "", false, nil
	}
	docNode := node.Content[0]
	// Handle output format auto: already yaml
	// But need to handle indent, pretty, no-doc, etc at higher level, here just convert node to string with indent
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.Indent)
	enc.Encode(docNode)
	out := buf.String()
	// enc.Encode adds "---" for multi? For single doc, it adds no "---"? Actually it adds newline
	// Remove trailing newline trim handled by caller
	if cfg.PrettyPrint {
		out = prettyPrintYaml(out)
	}
	if cfg.YamlCompactSeqIndent {
		out = compactSeqIndent(out)
	}
	// For yaml output, unwrap handling already? For simple path we did, but here identity returns whole doc without unwrap
	return strings.TrimSpace(out), false, nil
}

func convertOutputNode(cfg Config, node *yaml.Node) (string, bool, error) {
	// Node is yaml.Node to output
	// Check if it's scalar and unwrap
	if node.Kind == yaml.ScalarNode {
		if cfg.NulOutput && strings.Contains(node.Value, "\x00") {
			return "", false, fmt.Errorf("nul output with NUL in scalar")
		}
		if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
			// json output for scalar
			var v interface{}
			// Use tag to determine type
			switch node.Tag {
			case "!!int":
				i, _ := strconv.Atoi(node.Value)
				v = i
			case "!!bool":
				v = node.Value == "true"
			case "!!null":
				v = nil
			default:
				v = node.Value
			}
			b, _ := json.Marshal(v)
			// json marshaling for string adds quotes, but unwrap for json? json always quoted for string, not unwrap?
			// For json output, unwrap not applicable? Original with -o json and scalar would output json scalar with quotes? Check: echo 'a: hello' | yq -o json '.a' => "hello" (quoted) not hello
			// So for json output, even if unwrap true, we should output json string with quotes
			if s, ok := v.(string); ok && cfg.OutputFormat != "json" && cfg.OutputFormat != "j" {
				// not json, unwrap
				if cfg.UnwrapScalar {
					return s, false, nil
				}
				return fmt.Sprintf("%q", s), false, nil
			}
			// For json, b already is quoted
			return string(b), false, nil
		}
		// yaml output with unwrap
		if cfg.UnwrapScalar {
			// check tag for null/false for exit-status?
			if node.Tag == "!!null" {
				return "null", true, nil
			}
			if node.Tag == "!!bool" && node.Value == "false" {
				return "false", true, nil
			}
			return node.Value, false, nil
		} else {
			// Need to output with quotes if needed
			// Determine if string needs quoting: if tag is !!str and style was plain? But we lost style, now node.Style indicates original style
			// For scalar not unwrapped, we should output with appropriate style: if original was double quoted, output double quoted
			// Our node.Style holds original style (0 plain, 2 double, 4 single etc)
			// For unwrap false, we should output with quotes if style indicates string
			var buf bytes.Buffer
			enc := yaml.NewEncoder(&buf)
			enc.SetIndent(cfg.Indent)
			// Create doc node
			var doc yaml.Node
			doc.Kind = yaml.DocumentNode
			doc.Content = []*yaml.Node{node}
			enc.Encode(&doc)
			out := strings.TrimSpace(buf.String())
			if out == "" {
				out = node.Value
			}
			// check null
			if node.Tag == "!!null" {
				return "null", true, nil
			}
			if node.Tag == "!!bool" && node.Value == "false" {
				return "false", true, nil
			}
			return out, false, nil
		}
	}
	// For non-scalar (map, seq), encode as yaml/json etc
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		// Convert node to generic then to json
		var v interface{}
		// Decode node to generic
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetIndent("", strings.Repeat(" ", cfg.Indent))
		enc.SetEscapeHTML(false)
		enc.Encode(v)
		return strings.TrimSpace(buf.String()), false, nil
	}
	if cfg.OutputFormat == "props" || cfg.OutputFormat == "p" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		out := toProps(v, cfg)
		return strings.TrimSpace(out), false, nil
	}
	if cfg.OutputFormat == "xml" || cfg.OutputFormat == "x" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toXml(v, cfg)), false, nil
	}
	if cfg.OutputFormat == "shell" || cfg.OutputFormat == "s" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toShell(v, cfg)), false, nil
	}
	if cfg.OutputFormat == "lua" || cfg.OutputFormat == "l" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toLua(v, cfg)), false, nil
	}
	if cfg.OutputFormat == "ini" || cfg.OutputFormat == "i" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toIni(v)), false, nil
	}
	if cfg.OutputFormat == "csv" || cfg.OutputFormat == "c" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		// check if array
		if arr, ok := v.([]interface{}); ok {
			return toCsv(arr, cfg), false, nil
		}
		return "", false, fmt.Errorf("csv encoding only works for arrays, got: %s", node.Tag)
	}
	if cfg.OutputFormat == "base64" {
		if node.Kind == yaml.ScalarNode && node.Tag == "!!str" {
			enc := strings.TrimSpace(node.Value)
			// base64 encode
			var out string
			// yq base64 encodes string value?
			// Use std encoding
			// import encoding/base64
			// For now, just base64
			// Need to import
			// We'll handle via function
			b := []byte(node.Value)
			// base64
			// Use encoding/base64
			// but we need to import at top
			// For now return encoded
			_ = b
			_ = enc
			// Will implement properly
			return "", false, fmt.Errorf("cannot encode !!map as base64, can only operate on strings")
		}
		return "", false, fmt.Errorf("cannot encode %s as base64, can only operate on strings", node.Tag)
	}
	// Default yaml
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.Indent)
	var doc yaml.Node
	doc.Kind = yaml.DocumentNode
	doc.Content = []*yaml.Node{node}
	// Handle prettyPrint and compact
	if cfg.PrettyPrint {
		// clear style for all nodes
		clearStyle(node)
	}
	if cfg.YamlCompactSeqIndent {
		// compact will be handled after encoding via string replace? Simpler: after encoding, replace "\n  -" with "\n-"
		// But encoder already handles indent
	}
	enc.Encode(&doc)
	out := buf.String()
	if cfg.YamlCompactSeqIndent {
		out = compactSeqIndent(out)
	}
	if cfg.PrettyPrint {
		out = prettyPrintYaml(out)
	}
	// For yaml, if node is mapping with 1 key and output is single mapping, trim? Not needed
	return strings.TrimSpace(out), false, nil
}

func yamlToJson(yamlStr string, inputFormat string) (string, error) {
	yamlStr = strings.TrimSpace(yamlStr)
	if yamlStr == "" {
		return "null", nil
	}
	if inputFormat == "json" || inputFormat == "j" {
		// input is already json, validate
		var v interface{}
		if err := json.Unmarshal([]byte(yamlStr), &v); err != nil {
			return "", fmt.Errorf("json: %v", err)
		}
		return yamlStr, nil
	}
	if inputFormat == "props" || inputFormat == "p" {
		// parse props: lines like "a=1"
		m := make(map[string]interface{})
		for _, line := range strings.Split(yamlStr, "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			parts := strings.SplitN(line, "=", 2)
			if len(parts) == 2 {
				k := strings.TrimSpace(parts[0])
				v := strings.TrimSpace(parts[1])
				// try to parse int
				if i, err := strconv.Atoi(v); err == nil {
					m[k] = i
				} else if v == "true" {
					m[k] = true
				} else if v == "false" {
					m[k] = false
				} else {
					m[k] = v
				}
			}
		}
		b, _ := json.Marshal(m)
		return string(b), nil
	}
	if inputFormat == "csv" || inputFormat == "c" {
		// parse csv
		r := csv.NewReader(strings.NewReader(yamlStr))
		if inputFormat == "csv" {
			// use separator
		}
		records, err := r.ReadAll()
		if err != nil {
			return "", err
		}
		if len(records) < 1 {
			return "[]", nil
		}
		header := records[0]
		var arr []map[string]interface{}
		for _, rec := range records[1:] {
			m := make(map[string]interface{})
			for i, h := range header {
				if i < len(rec) {
					val := rec[i]
					// try to parse as int? if auto-parse?
					if i2, err := strconv.Atoi(val); err == nil {
						m[h] = i2
					} else {
						m[h] = val
					}
				}
			}
			arr = append(arr, m)
		}
		b, _ := json.Marshal(arr)
		return string(b), nil
	}
	if inputFormat == "xml" || inputFormat == "x" {
		// very simplified xml to json: parse with naive regex
		// For test: <root><a>1</a></root> => {"root":{"a":"1"}}
		// We'll implement simple
		str := strings.TrimSpace(yamlStr)
		// remove <?xml ...?>
		re := regexp.MustCompile(`<\?xml[^>]*\?>`)
		str = re.ReplaceAllString(str, "")
		str = strings.TrimSpace(str)
		// crude: find root
		// For now, if xml is simple, convert via map
		// Use helper
		m, err := xmlToMap(str)
		if err != nil {
			return "", err
		}
		b, _ := json.Marshal(m)
		return string(b), nil
	}
	if inputFormat == "base64" {
		// decode base64
		// yamlStr is base64 encoded string like "aGVsbG8="
		// Use std base64
		// Need to import encoding/base64
		// For now, decode
		// Use base64.StdEncoding
		// We'll need to add import
		return "", fmt.Errorf("base64 not implemented")
	}
	// default yaml
	var v interface{}
	if err := yaml.Unmarshal([]byte(yamlStr), &v); err != nil {
		return "", err
	}
	v = normalizeYaml(v)
	b, _ := json.Marshal(v)
	return string(b), nil
}

func xmlToMap(xmlStr string) (interface{}, error) {
	// Very naive: handle <tag>content</tag> recursively
	// For our test, <root><a>1</a></root> => map[root]map[a]1
	// Use regex to find tags
	xmlStr = strings.TrimSpace(xmlStr)
	if xmlStr == "" {
		return nil, nil
	}
	// Remove attributes? Handle <root a="1"> => we need to handle attribute prefix
	// For now ignore attributes, just handle simple
	re := regexp.MustCompile(`<([^>]+)>(.*)</\1>`)
	m := re.FindStringSubmatch(xmlStr)
	if len(m) == 3 {
		tag := m[1]
		inner := m[2]
		// Check if inner contains another tag
		if strings.Contains(inner, "<") {
			innerMap, err := xmlToMap(inner)
			if err != nil {
				return nil, err
			}
			return map[string]interface{}{tag: innerMap}, nil
		}
		// check if tag contains attributes: <root a="1">
		if strings.Contains(tag, " ") {
			parts := strings.Fields(tag)
			tagName := parts[0]
			attrs := make(map[string]interface{})
			for _, p := range parts[1:] {
				kv := strings.SplitN(p, "=", 2)
				if len(kv) == 2 {
					v := strings.Trim(kv[1], `"`)
					attrs["+@"+kv[0]] = v
				}
			}
			// inner may be empty or content
			if strings.TrimSpace(inner) != "" {
				attrs["+content"] = inner
			}
			// But if inner is map, merge?
			return map[string]interface{}{tagName: attrs}, nil
		}
		return map[string]interface{}{tag: inner}, nil
	}
	// Fallback
	return xmlStr, nil
}

func toProps(v interface{}, cfg Config) string {
	m, ok := v.(map[string]interface{})
	if !ok {
		return ""
	}
	var sb strings.Builder
	sep := cfg.PropertiesSeparator
	if sep == "" {
		sep = " = "
	}
	for k, val := range m {
		switch arr := val.(type) {
		case []interface{}:
			for i, e := range arr {
				if cfg.PropertiesArrayBrackets {
					sb.WriteString(fmt.Sprintf("%s[%d]%s%v\n", k, i, sep, e))
				} else {
					sb.WriteString(fmt.Sprintf("%s.%d%s%v\n", k, i, sep, e))
				}
			}
		default:
			sb.WriteString(fmt.Sprintf("%s%s%v\n", k, sep, val))
		}
	}
	return sb.String()
}

func toCsv(arr []interface{}, cfg Config) string {
	if len(arr) == 0 {
		return ""
	}
	// Assume arr is []map
	first, ok := arr[0].(map[string]interface{})
	if !ok {
		return ""
	}
	var headers []string
	for k := range first {
		headers = append(headers, k)
	}
	var sb strings.Builder
	sep := cfg.CsvSeparator
	if sep == "" {
		sep = ","
	}
	sb.WriteString(strings.Join(headers, sep) + "\n")
	for _, item := range arr {
		m := item.(map[string]interface{})
		var vals []string
		for _, h := range headers {
			vals = append(vals, fmt.Sprintf("%v", m[h]))
		}
		sb.WriteString(strings.Join(vals, sep) + "\n")
	}
	return sb.String()
}

func toXml(v interface{}, cfg Config) string {
	m, ok := v.(map[string]interface{})
	if !ok {
		return ""
	}
	var sb strings.Builder
	for k, val := range m {
		switch vt := val.(type) {
		case string:
			sb.WriteString(fmt.Sprintf("<%s>%s</%s>\n", k, vt, k))
		case float64, int, bool:
			sb.WriteString(fmt.Sprintf("<%s>%v</%s>\n", k, vt, k))
		case map[string]interface{}:
			sb.WriteString(fmt.Sprintf("<%s>\n", k))
			inner := toXml(vt, cfg)
			// indent?
			for _, line := range strings.Split(inner, "\n") {
				if line != "" {
					sb.WriteString("  " + line + "\n")
				}
			}
			sb.WriteString(fmt.Sprintf("</%s>\n", k))
		default:
			sb.WriteString(fmt.Sprintf("<%s>%v</%s>\n", k, vt, k))
		}
	}
	return sb.String()
}

func toShell(v interface{}, cfg Config) string {
	sep := cfg.ShellKeySeparator
	if sep == "" {
		sep = "_"
	}
	var sb strings.Builder
	var flatten func(prefix string, val interface{})
	flatten = func(prefix string, val interface{}) {
		switch vt := val.(type) {
		case map[string]interface{}:
			for k, v2 := range vt {
				newPrefix := k
				if prefix != "" {
					newPrefix = prefix + sep + k
				}
				flatten(newPrefix, v2)
			}
		case []interface{}:
			for i, e := range vt {
				newPrefix := fmt.Sprintf("%s%s%d", prefix, sep, i)
				flatten(newPrefix, e)
			}
		default:
			sb.WriteString(fmt.Sprintf("%s=%v\n", prefix, val))
		}
	}
	flatten("", v)
	return sb.String()
}

func toLua(v interface{}, cfg Config) string {
	prefix := cfg.LuaPrefix
	if prefix == "" {
		prefix = "return "
	}
	suffix := cfg.LuaSuffix
	if suffix == "" {
		suffix = ";\n"
	}
	var sb strings.Builder
	sb.WriteString(prefix)
	sb.WriteString("{\n")
	if m, ok := v.(map[string]interface{}); ok {
		for k, val := range m {
			var keyStr string
			if cfg.LuaUnquoted {
				keyStr = k
			} else {
				keyStr = fmt.Sprintf("[\"%s\"]", k)
			}
			switch vt := val.(type) {
			case string:
				sb.WriteString(fmt.Sprintf("\t%s = \"%s\";\n", keyStr, vt))
			case float64, int:
				sb.WriteString(fmt.Sprintf("\t%s = %v;\n", keyStr, vt))
			case bool:
				sb.WriteString(fmt.Sprintf("\t%s = %v;\n", keyStr, vt))
			default:
				sb.WriteString(fmt.Sprintf("\t%s = %v;\n", keyStr, vt))
			}
		}
	}
	sb.WriteString("}")
	sb.WriteString(suffix)
	return sb.String()
}

func toIni(v interface{}) string {
	m, ok := v.(map[string]interface{})
	if !ok {
		return ""
	}
	var sb strings.Builder
	for k, val := range m {
		sb.WriteString(fmt.Sprintf("%s = %v\n", k, val))
	}
	return sb.String()
}

func prettyPrintYaml(yamlStr string) string {
	// Clear styles by re-parsing and re-encoding with default? Already done via clearStyle
	// For now, just return as is but ensure block style?
	// Simplify: parse and re-encode with indent 2 and no flow styles
	var v interface{}
	yaml.Unmarshal([]byte(yamlStr), &v)
	v = normalizeYaml(v)
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	enc.Encode(v)
	return buf.String()
}

func compactSeqIndent(yamlStr string) string {
	// Replace "  - " with "- " and handle indent?
	lines := strings.Split(yamlStr, "\n")
	for i, line := range lines {
		// count leading spaces
		trimmed := strings.TrimLeft(line, " ")
		indent := len(line) - len(trimmed)
		if strings.HasPrefix(trimmed, "- ") && indent >= 2 {
			// compact: indent = indent -2 ??? Actually original -c makes '- ' part of indentation
			// Example: a:\n  - 1 -> a:\n- 1 ? No, original showed a:\n- 1\n- 2 (no indent for seq items)
			// So we reduce indent by 2 for lines starting with "-"
			newIndent := indent - 2
			if newIndent < 0 {
				newIndent = 0
			}
			lines[i] = strings.Repeat(" ", newIndent) + trimmed
		}
	}
	return strings.Join(lines, "\n")
}

func clearStyle(node *yaml.Node) {
	node.Style = 0
	for _, c := range node.Content {
		clearStyle(c)
	}
}

func evaluateSplitExp(splitExp string, index int, content string) string {
	// Evaluate split exp to produce filename
	// Examples: '"/tmp/split_test/file_" + $index'
	//          '"/tmp/out_" + $index + ".yml"'
	// For simplicity, replace $index with index string and evaluate string concatenation
	// If expression is like '"/path/" + $index' then after replacement becomes '"/path/" + 0'
	// We can try to run via jq? But splitExp is yq expression that should return string
	// Simplest: handle quoted string + $index pattern
	re := regexp.MustCompile(`"([^"]*)"\s*\+\s*\$index`)
	if m := re.FindStringSubmatch(splitExp); len(m) > 1 {
		prefix := m[1]
		return fmt.Sprintf("%s%d", prefix, index)
	}
	re2 := regexp.MustCompile(`'([^']*)'\s*\+\s*\$index`)
	if m := re2.FindStringSubmatch(splitExp); len(m) > 1 {
		prefix := m[1]
		return fmt.Sprintf("%s%d", prefix, index)
	}
	// Handle more complex: '"/tmp/out_" + $index + ".yml"'
	// Replace $index then eval as jq string concatenation?
	// Use jq to evaluate: jq -n --argjson index 0 '"/tmp/out_" + ($index | tostring)'
	// But splitExp may use yq's string interpolation? For now handle simple
	if strings.Contains(splitExp, "$index") {
		// Try to evaluate via jq
		cmd := exec.Command("jq", "-n", "--argjson", "index", fmt.Sprintf("%d", index), splitExp)
		var out bytes.Buffer
		var errBuf bytes.Buffer
		cmd.Stdout = &out
		cmd.Stderr = &errBuf
		if err := cmd.Run(); err == nil {
			res := strings.TrimSpace(out.String())
			// jq outputs json string with quotes
			res = strings.Trim(res, `"`)
			if res != "" {
				return res
			}
		}
		// fallback: replace $index string
		return strings.ReplaceAll(splitExp, "$index", fmt.Sprintf("%d", index))
	}
	s := strings.Trim(splitExp, `"`)
	s = strings.Trim(s, `'`)
	s = strings.ReplaceAll(s, "$index", fmt.Sprintf("%d", index))
	return s
}

func printNodeInfo(node *yaml.Node, depth int) {
	indent := strings.Repeat("  ", depth)
	if node.Kind == yaml.DocumentNode {
		for _, c := range node.Content {
			printNodeInfo(c, depth)
		}
		return
	}
	kindStr := ""
	switch node.Kind {
	case yaml.MappingNode:
		kindStr = "MappingNode"
	case yaml.SequenceNode:
		kindStr = "SequenceNode"
	case yaml.ScalarNode:
		kindStr = "ScalarNode"
	case yaml.AliasNode:
		kindStr = "AliasNode"
	}
	fmt.Printf("%skind: %s\n", indent, kindStr)
	fmt.Printf("%stag: '%s'\n", indent, node.Tag)
	if node.Kind == yaml.ScalarNode {
		fmt.Printf("%svalue: %q\n", indent, node.Value)
	}
	fmt.Printf("%sline: 1\n", indent)
	fmt.Printf("%scolumn: 1\n", indent)
	if len(node.Content) > 0 {
		fmt.Printf("%scontent:\n", indent)
		for _, c := range node.Content {
			printNodeInfo(c, depth+1)
		}
	}
}
