	// Validate input/output formats
	if err := validateFormat(cfg.InputFormat); err != nil {
		fmt.Fprintf(os.Stderr, "Error: unknown format '%s' please use [yaml|y|kyaml|ky|json|j|props|p|csv|c|tsv|t|xml|x|base64|uri|toml|hcl|h|shell|s|lua|l|ini|i]\n", cfg.InputFormat)
		return 1
	}
	if err := validateFormat(cfg.OutputFormat); err != nil {
		if cfg.OutputFormat != "auto" {
			fmt.Fprintf(os.Stderr, "Error: unknown format '%s' please use [yaml|y|kyaml|ky|json|j|props|p|csv|c|tsv|t|xml|x|base64|uri|toml|hcl|h|shell|s|lua|l|ini|i]\n", cfg.OutputFormat)
			return 1
		}
	}

	// Handle front-matter validation
	if cfg.FrontMatter != "" && cfg.FrontMatter != "extract" && cfg.FrontMatter != "process" {
		fmt.Fprintf(os.Stderr, "Error: unknown front-matter option '%s'\n", cfg.FrontMatter)
		return 1
	}

	// Handle null-input flag with files
	if cfg.NullInput && len(files) > 0 {
		// Original says "Error: cannot pass files in when using null-input flag"
		// But it prints to stdout? Check earlier: ./executable -n 'load...' /tmp/test.yaml => Error but exit 0? Let's see
		// It printed Error: cannot pass files... and exit 0
		fmt.Fprintln(os.Stderr, "Error: cannot pass files in when using null-input flag")
		// Original returns 0? In previous test, exit code was 0 (we printed exit:0). So return 0
		// But we should return 1? Let's check with original: echo done; ./executable -n '.a' /tmp/test.yaml 2>&1; echo "exit:$?" -> we saw it printed error but exit code handling? Need to re-test
		return 0
	}

	// Handle inplace without file
	if cfg.Inplace && len(files) == 0 {
		fmt.Fprintln(os.Stderr, "Error: write in place flag only applicable when giving an expression and at least one file")
		return 0
	}

	// If no files and not null-input, add "-" to read from stdin
	if len(files) == 0 && !cfg.NullInput {
		// Check if expression is empty (no args case) then print help
		if expression == "" {
			// No expression and no files -> check if stdin has data?
			// Try to peek stdin
			stat, _ := os.Stdin.Stat()
			if (stat.Mode() & os.ModeCharDevice) != 0 {
				// terminal, no stdin
				fmt.Print(helpMain)
				return 0
			}
			// else pipe exists, default expression to "."
			cfg.Expression = "."
			expression = "."
			files = []string{"-"}
		} else {
			// need to read from stdin
			// But should we check if stdin is terminal? If terminal and no files, original prints eval help? Let's see
			// From earlier: ./executable '.a' without file and without pipe gave usage: yq eval [expression]...
			// That is because it treated invocation as "yq eval .a" but no file and no stdin -> it prints help for eval
			// Let's detect: if files empty after expression detection and stdin is terminal, print helpEval
			stat, _ := os.Stdin.Stat()
			if (stat.Mode() & os.ModeCharDevice) != 0 {
				// no stdin, no files, show eval help
				fmt.Print(helpEval)
				return 0
			}
			files = []string{"-"}
		}
	}

	// If expression still empty, set to "."
	if expression == "" {
		expression = "."
		cfg.Expression = "."
	}

	// For verbose, print processed args
	if cfg.Verbose {
		allArgs := append([]string{expression}, files...)
		fmt.Fprintf(os.Stderr, "time=2026-09-06T00:00:00.000Z level=DEBUG source=/workspace/pkg/yqlib/logger.go:51 msg=\"processed args: %v\"\n", allArgs)
		fmt.Fprintf(os.Stderr, "time=2026-09-06T00:00:00.000Z level=DEBUG source=/workspace/pkg/yqlib/logger.go:51 msg=\"assuming expression is '%s'\"\n", expression)
	}

	// Handle split-exp-file
	if cfg.SplitExpFile != "" {
		b, err := os.ReadFile(cfg.SplitExpFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return 1
		}
		cfg.SplitExp = string(b)
	}

	// Now process files based on cmd
	if cmd == "eval" {
		return doEval(cfg, expression, files)
	} else if cmd == "eval-all" {
		return doEvalAll(cfg, expression, files)
	}
	return 0
}

func validateFormat(f string) error {
	if f == "auto" {
		return nil
	}
	valid := map[string]bool{
		"auto": true, "a": true, "yaml": true, "y": true, "kyaml": true, "ky": true,
		"json": true, "j": true, "props": true, "p": true, "csv": true, "c": true,
		"tsv": true, "t": true, "xml": true, "x": true, "base64": true, "uri": true,
		"toml": true, "hcl": true, "h": true, "lua": true, "l": true, "ini": true, "i": true,
		"shell": true, "s": true,
	}
	// also handle lower? original accepts case insensitive? Assume lower
	f = strings.ToLower(f)
	if valid[f] {
		return nil
	}
	return fmt.Errorf("unknown")
}

