func runNullInput(cfg Config, expression string) int {
	// Handle null-input: evaluate expression without input, create docs from scratch
	// Examples: -n '"hello"' -> string hello
	// -n '.a = 1 | .b = 2' -> yaml with a:1 b:2
	// -n 'load("file")' -> load file
	// We need to handle these via jq or custom

	// Security checks
	if cfg.SecurityDisableEnvOps && strings.Contains(expression, "strenv") {
		fmt.Fprintln(os.Stderr, "Error: env operations have been disabled")
		return 1
	}
	if cfg.SecurityDisableFileOps && strings.Contains(expression, "load") {
		fmt.Fprintln(os.Stderr, "Error: file operations have been disabled")
		return 1
	}

	// Try to handle via jq with null input
	// jq -n 'expression'
	cmd := exec.Command("jq", "-n", expression)
	// Set env for jq to access via $ENV if needed
	cmd.Env = os.Environ()
	var out bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errBuf
	err := cmd.Run()
	if err != nil {
		// Check if expression is yq-specific like load()
		if strings.Contains(expression, "load(") {
			return handleLoadExpression(cfg, expression)
		}
		// Handle strenv case: translate strenv(NAME) to $ENV.NAME
		if strings.Contains(expression, "strenv") {
			translated := translateStrenv(expression)
			cmd2 := exec.Command("jq", "-n", translated)
			cmd2.Env = os.Environ()
			var out2 bytes.Buffer
			var errBuf2 bytes.Buffer
			cmd2.Stdout = &out2
			cmd2.Stderr = &errBuf2
			if err2 := cmd2.Run(); err2 == nil {
				return outputJqResult(cfg, out2.String())
			}
			fmt.Fprintf(os.Stderr, "Error: %s\n", strings.TrimSpace(errBuf.String()))
			return 1
		}
		fmt.Fprintf(os.Stderr, "Error: %s\n", strings.TrimSpace(errBuf.String()))
		// original prints "Error: 1:1: lexer: ..." for invalid, we already handled validation, but jq error is different
		// For now just return error
		return 1
	}
	return outputJqResult(cfg, out.String())
}

func translateStrenv(expr string) string {
	// Replace strenv(VAR) with $ENV.VAR or $ENV["VAR"]
	re := regexp.MustCompile(`strenv\(([^)]+)\)`)
	return re.ReplaceAllStringFunc(expr, func(m string) string {
		sub := re.FindStringSubmatch(m)
		if len(sub) > 1 {
			varName := strings.TrimSpace(sub[1])
			varName = strings.Trim(varName, `"`)
			varName = strings.Trim(varName, `'`)
			// handle if varName is already quoted?
			return fmt.Sprintf(`$ENV["%s"]`, varName)
		}
		return m
	})
}

func handleLoadExpression(cfg Config, expression string) int {
	// Extract load("file") references and replace with file content json
	// Example: load("/tmp/a.yaml") * load("/tmp/b.yaml")
	re := regexp.MustCompile(`load\("([^"]+)"\)`)
	matches := re.FindAllStringSubmatch(expression, -1)
	if len(matches) == 0 {
		fmt.Fprintf(os.Stderr, "Error: %v\n", "load failed")
		return 1
	}
	// For each load, read file and convert to json
	replacements := make(map[string]string)
	for _, m := range matches {
		filename := m[1]
		data, err := os.ReadFile(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return 1
		}
		// Detect format based on extension or inputFormat
		var jsonStr string
		// Try to parse as yaml and convert to json
		var v interface{}
		if err := yaml.Unmarshal(data, &v); err != nil {
			// try json?
			var v2 interface{}
			if err2 := json.Unmarshal(data, &v2); err2 != nil {
				jsonStr = fmt.Sprintf(`"%s"`, string(data))
			} else {
				b, _ := json.Marshal(v2)
				jsonStr = string(b)
			}
		} else {
			v = normalizeYaml(v)
			b, _ := json.Marshal(v)
			jsonStr = string(b)
		}
		replacements[m[0]] = jsonStr
	}
	newExpr := expression
	for old, newVal := range replacements {
		newExpr = strings.ReplaceAll(newExpr, old, newVal)
	}
	// Now run jq with newExpr: it should be like '{"a":1} * {"b":2}' which jq can handle as: jq -n '{"a":1} * {"b":2}'
	// Need to wrap as jq expression: the json objects are values, need to evaluate multiplication
	// So newExpr is like '{"a":1} * {"b":2}' which is valid jq that will produce merged?
	// Test: jq -n '{"a":1} * {"b":2}' should work
	cmd := exec.Command("jq", "-n", newExpr)
	var out bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errBuf
	if err := cmd.Run(); err != nil {
		// Fallback to Go merge
		// If expression is just load * load, do merge via Go
		var docs []interface{}
		for _, m := range matches {
			filename := m[1]
			data, _ := os.ReadFile(filename)
			var v interface{}
			yaml.Unmarshal(data, &v)
			v = normalizeYaml(v)
			docs = append(docs, v)
		}
		if len(docs) > 0 {
			result := docs[0]
			for i := 1; i < len(docs); i++ {
				result = mergeMaps(result, docs[i])
			}
			// output result
			var buf bytes.Buffer
			enc := yaml.NewEncoder(&buf)
			enc.SetIndent(cfg.Indent)
			enc.Encode(result)
			outStr := buf.String()
			if cfg.OutputFormat == "json" {
				var b bytes.Buffer
				je := json.NewEncoder(&b)
				je.SetIndent("", strings.Repeat(" ", cfg.Indent))
				je.Encode(result)
				outStr = b.String()
			}
			fmt.Print(outStr)
			return 0
		}
		fmt.Fprintf(os.Stderr, "Error: %s\n", errBuf.String())
		return 1
	}
	return outputJqResult(cfg, out.String())
}

func outputJqResult(cfg Config, jqOutput string) int {
	jqOutput = strings.TrimSpace(jqOutput)
	if jqOutput == "" {
		return 0
	}
	// jq output may be multiple json values separated by newline (compact or pretty)
	// Need to detect if output is multiple docs
	// jq -n with expression that produces object will output pretty printed json with newlines
	// But if expression is '"hello"' then output is "\"hello\"\n"
	// We need to handle scalar unwrapping and output format

	// For null-input with simple expression like '"hello"', jq outputs "\"hello\"" (json string)
	// yq should output unwrapped scalar "hello" if unwrapScalar true and output is yaml
	// Check: ./executable -n '"hello"' outputs hello (unwrapped) per earlier test
	// So we need to handle unwrapping

	// Split jq output into separate JSON values: for jq -n, it outputs one value, but for jq with multiple outputs (like .a[]), it would be multiple
	// For null-input, it's single value

	// Try to parse jqOutput as JSON
	var data interface{}
	if err := json.Unmarshal([]byte(jqOutput), &data); err != nil {
		// Might be multiple lines pretty printed: json.Unmarshal will fail for pretty multi-line object? Actually json.Unmarshal can handle pretty with whitespace
		// Let's try to handle by using json decoder that reads first value
		dec := json.NewDecoder(strings.NewReader(jqOutput))
		var first interface{}
		if err := dec.Decode(&first); err == nil {
			data = first
		} else {
			// fallback: treat as raw string
			fmt.Print(jqOutput)
			if !strings.HasSuffix(jqOutput, "\n") {
				fmt.Println()
			}
			return 0
		}
	}

	// Now output based on format
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		// output as json with indent
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetIndent("", strings.Repeat(" ", cfg.Indent))
		enc.SetEscapeHTML(false)
		enc.Encode(data)
		fmt.Print(buf.String())
		return 0
	}
	// default yaml
	if data == nil {
		// yaml null
		if cfg.UnwrapScalar {
			fmt.Println("null")
			return 0
		}
		fmt.Println("null")
		return 0
	}
	switch v := data.(type) {
	case string:
		if cfg.UnwrapScalar {
			fmt.Println(v)
			return 0
		}
		// need to output quoted string as yaml?
		fmt.Printf("%q\n", v)
		return 0
	case float64, int, bool:
		if cfg.UnwrapScalar {
			fmt.Printf("%v\n", v)
			return 0
		}
	}

	// For complex types, encode as yaml
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.Indent)
	enc.Encode(data)
	outStr := buf.String()
	if cfg.PrettyPrint {
		outStr = prettyPrintYaml(outStr)
	}
	fmt.Print(outStr)
	return 0
}

func evaluateExpression(cfg Config, expression string, docContent string, docInfo Doc) (string, bool, error) {
	// Handle debug already
	// Validate expression first
	if err := validateExpression(expression); err != nil {
		return "", false, err
	}

	// Special handling for string interpolation disable
	if !cfg.StringInterpolation && strings.Contains(expression, "\\(") {
		// If disabled, treat "\(exp)" as literal
		// yq with --string-interpolation=false would output literal string "\(.a)" => but our test showed it outputs "\(.a)" ?
		// Actually echo 'a: 1' | yq --string-interpolation=false '"\(.a)"' gave literal "\(.a)"? Let's check original: it gave "\(.a)"
		// So we should return literal without interpolation
		// For now, if expression contains "\(" and interpolation false, just output the expression string content without evaluating inner?
		// Simplified: return the expression's quoted content without processing
		// Expression '"\(.a)"' when interpolation false should output string "\(.a)" unwrapped? But original gave "\(.a)" (with escaping)?
		// We'll just return the raw string without quotes if unwrap
		trim := strings.Trim(expression, `"`)
		trim = strings.Trim(trim, `'`)
		if cfg.UnwrapScalar {
			return trim, false, nil
		}
		return fmt.Sprintf("%q", trim), false, nil
	}

	// Handle simple cases without jq for performance and style preservation
	if expression == "." {
		// identity - return docContent as is, but handle output format conversion
		return convertOutput(cfg, docContent, docInfo)
	}
	if isSimplePath(expression) {
		return evaluateSimplePath(cfg, expression, docContent)
	}
	// Handle assignment: ".a = 2" or ".a.b = \"hello\"" etc
	if strings.Contains(expression, "=") && !strings.Contains(expression, "==") && !strings.Contains(expression, "!=") && !strings.Contains(expression, "=~") {
		return evaluateAssignment(cfg, expression, docContent)
	}
	// Handle pipe and other jq expressions: use jq

	// Preprocess yq-specific functions
	expr := expression
	// Handle strenv
	if strings.Contains(expr, "strenv") {
		if cfg.SecurityDisableEnvOps {
			return "", false, fmt.Errorf("env operations have been disabled")
		}
		expr = translateStrenv(expr)
	}
	if strings.Contains(expr, "env(") && cfg.SecurityDisableEnvOps {
		return "", false, fmt.Errorf("env operations have been disabled")
	}
	if strings.Contains(expr, "load(") {
		if cfg.SecurityDisableFileOps {
			return "", false, fmt.Errorf("file operations have been disabled")
		}
		// Handle load via replacement
		re := regexp.MustCompile(`load\("([^"]+)"\)`)
		matches := re.FindAllStringSubmatch(expr, -1)
		for _, m := range matches {
			filename := m[1]
			data, err := os.ReadFile(filename)
			if err != nil {
				return "", false, fmt.Errorf("bad file '%s': %v", filename, err)
			}
			var v interface{}
			if err := yaml.Unmarshal(data, &v); err != nil {
				return "", false, err
			}
			v = normalizeYaml(v)
			b, _ := json.Marshal(v)
			expr = strings.ReplaceAll(expr, m[0], string(b))
		}
	}
	// Handle string interpolation for yq: already jq supports similar, but yq's \(exp) inside strings is like jq
	// jq also supports that, so no need to translate

	// Convert yaml doc to json
	jsonStr, err := yamlToJson(docContent, cfg.InputFormat)
	if err != nil {
		// If input is not yaml? Try to handle empty?
		if strings.TrimSpace(docContent) == "" {
			jsonStr = "null"
		} else {
			return "", false, fmt.Errorf("bad file '-': %v", err)
		}
	}
	if jsonStr == "" {
		jsonStr = "null"
	}
	// Run jq
	// Need to handle $index, $fileIndex etc? For eval, those variables may be used but we don't support; if present, handle via eval-all path
	// For now, just run jq
	cmd := exec.Command("jq", expr)
	cmd.Stdin = strings.NewReader(jsonStr)
	cmd.Env = os.Environ()
	var outBuf bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	err = cmd.Run()
	if err != nil {
		// Check if jq output is empty and error is about no input? For select returning false, jq exits 0 with empty
		// But for error like "foo", jq returns error
		errStr := strings.TrimSpace(errBuf.String())
		if errStr == "" {
			errStr = err.Error()
		}
		// Map jq errors to yq errors? Original errors like "Error: foo" for 'error("foo")'
		// yq's error() function produces "Error: foo"
		// jq's error() produces "jq: error (at <stdin>:1): foo"
		// We should extract message
		if strings.Contains(errStr, "error") {
			// try to extract foo
			re := regexp.MustCompile(`error.*?:\s*(.+)`)
			m := re.FindStringSubmatch(errStr)
			if len(m) > 1 {
				return "", false, fmt.Errorf("%s", strings.Trim(m[1], `"`))
			}
		}
		return "", false, fmt.Errorf("%s", errStr)
	}
	outStr := strings.TrimSpace(outBuf.String())
	if outStr == "" {
		// select returned no match -> indicate no output
		return "", false, nil
	}
	// jq may output multiple JSON values separated by newline (for .a[] etc)
	// For yq, each output should be separate doc: we need to handle that our caller expects single result per doc, but if jq produced multiple, we should join with "---" or return as multiple?
	// Our current per-doc loop expects single output per doc, but .a[] produces multiple lines like "1\n2\n3"
	// yq outputs each as separate line without "---" when unwrap? Let's check original: echo 'a: [1,2,3]' | yq '.a[]' gave "1\n2\n3\n" (no "---")
	// While multi-doc with "---" is for multiple docs: e.g., two docs each with . output gives "a:1\n---\nb:2\n"
	// For array expansion, it's not docs but stream of values, yq outputs each value without separator? Actually test showed "1\n2\n3\n" with no "---"
	// But if we use -N false, then docs separator is "---", but for stream values, still no separator? Let's assume stream values are joined by "\n" (original does \n)
	// So for per-doc, if jq output contains multiple json values (like "1\n2\n3"), we should treat as single output with newline joining (no "---")
	// Our caller will then handle joining outputs with "---" between docs, but stream values within doc should already be newline separated without "---"
	// So we can just return outStr as is, and caller will treat it as one output string
	// But when output is json/yaml object, outStr will be pretty printed with newlines internal, but that's part of one object, not multiple
	// How to distinguish? jq -c would give compact per value without internal newlines, but we use default (pretty)
	// jq default for object is pretty with newlines, but for multiple values it would be multiple pretty objects separated by newline: "{\n  \"a\":1\n}\n{\n  \"b\":2\n}" ?
	// That's ambiguous
	// To avoid, we can use jq -c for per-doc? Then we can parse and reformat according to output format
	// Alternative: use jq -c and then convert back to yaml with our formatting

	// For now, we'll try to parse outStr as JSON stream
	// If output format is yaml and unwrapScalar true, we need to handle scalars unwrapped
	// Let's detect if outStr is multiple json values
	dec := json.NewDecoder(strings.NewReader(outBuf.String()))
	var results []string
	for {
		var v interface{}
		if err := dec.Decode(&v); err != nil {
			if err == io.EOF {
				break
			}
			// fallback to raw
			results = []string{outStr}
			break
		}
		// Encode v to output format
		var res string
		if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
			b, _ := json.MarshalIndent(v, "", strings.Repeat(" ", cfg.Indent))
			// json.MarshalIndent adds newline, we trim?
			res = string(b)
		} else {
			// yaml
			if v == nil {
				res = "null"
				if !cfg.UnwrapScalar {
					res = "null"
				}
			} else if s, ok := v.(string); ok && cfg.UnwrapScalar {
				// check if original yaml scalar style? For now unwrap
				// Also check NUL output check: if scalar contains NUL and NulOutput true, error
				if cfg.NulOutput && strings.Contains(s, "\x00") {
					return "", false, fmt.Errorf("nul output with NUL in scalar")
				}
				res = s
			} else if _, ok := v.(float64); ok && cfg.UnwrapScalar {
				// numbers unwrapped
				// Use json number formatting
				b, _ := json.Marshal(v)
				res = string(b)
			} else if b, ok := v.(bool); ok && cfg.UnwrapScalar {
				if b {
					res = "true"
				} else {
					res = "false"
				}
			} else {
				// complex
				var buf bytes.Buffer
				enc := yaml.NewEncoder(&buf)
				enc.SetIndent(cfg.Indent)
				enc.Encode(v)
				res = strings.TrimSpace(buf.String())
				if cfg.PrettyPrint {
					res = prettyPrintYaml(res)
				}
				if cfg.YamlCompactSeqIndent {
					res = compactSeqIndent(res)
				}
			}
		}
		results = append(results, res)
	}
	if len(results) == 0 {
		return "", false, nil
	}
	if len(results) == 1 {
		// Check for null/false for exit-status? Caller handles
		out := results[0]
		isNull := strings.TrimSpace(out) == "null" || strings.TrimSpace(out) == "false"
		// Also handle case where output was "null" but we want to return "null" string for printing?
		// Original prints "null" for ".b" missing, with exit-status errors
		// So we should return "null" for printing, but also indicate isNull for exit logic
		if isNull {
			return out, true, nil
		}
		return out, false, nil
	}
	// Multiple results from one doc (like .a[])
	// Join with "\n" without "---"
	joined := strings.Join(results, "\n")
	return joined, false, nil
}

