func isSimplePath(expr string) bool {
	expr = strings.TrimSpace(expr)
	if expr == "." {
		return true
	}
	// reject if contains operators
	if strings.ContainsAny(expr, "=|*+(),\"'") {
		// But simple path could be .a.b with no operators, we already check
		// However path like .a.b[0] contains [ and ], but not in above charset? we excluded [ ] 
		// So check more
		if strings.Contains(expr, "=") || strings.Contains(expr, "|") || strings.Contains(expr, "*") || strings.Contains(expr, "+") || strings.Contains(expr, "(") || strings.Contains(expr, ")") || strings.Contains(expr, ",") {
			return false
		}
		if strings.Contains(expr, "\"") || strings.Contains(expr, "'") {
			return false
		}
	}
	if strings.Contains(expr, "select") || strings.Contains(expr, "load") || strings.Contains(expr, "strenv") || strings.Contains(expr, "env") {
		return false
	}
	if !strings.HasPrefix(expr, ".") {
		return false
	}
	// Check pattern: dot followed by word chars and brackets and dots
	re := regexp.MustCompile(`^\.(\w+(\[\d+\])?)?(\.\w+(\[\d+\])?)*$`)
	return re.MatchString(expr)
}

func evaluateSimplePath(cfg Config, expr string, docContent string) (string, bool, error) {
	// Parse yaml doc to Node
	var node yaml.Node
	if err := yaml.Unmarshal([]byte(docContent), &node); err != nil {
		// Try to handle empty
		if strings.TrimSpace(docContent) == "" {
			// empty doc -> treat as null
			return "null", true, nil
		}
		return "", false, err
	}
	// node is DocumentNode, content[0] is actual doc
	if len(node.Content) == 0 {
		return "null", true, nil
	}
	docNode := node.Content[0]

	// Special case "." returns whole doc
	if expr == "." {
		return convertOutputNode(cfg, docNode)
	}
	// Traverse path
	// Remove leading "."
	path := strings.TrimPrefix(expr, ".")
	parts := strings.Split(path, ".")
	current := docNode
	for _, part := range parts {
		if part == "" {
			continue
		}
		// Check for array index: e.g., "a[0]" or "a" without index
		re := regexp.MustCompile(`^(\w+)(?:\[(\d+)\])?$`)
		m := re.FindStringSubmatch(part)
		if m == nil {
			return "", false, fmt.Errorf("invalid path %s", part)
		}
		key := m[1]
		idxStr := m[2]

		// current should be MappingNode
		if current.Kind != yaml.MappingNode {
			// if trying to access field of non-map, return null
			return "null", true, nil
		}
		found := false
		var valueNode *yaml.Node
		for i := 0; i < len(current.Content); i += 2 {
			k := current.Content[i]
			v := current.Content[i+1]
			if k.Value == key {
				valueNode = v
				found = true
				break
			}
		}
		if !found {
			return "null", true, nil
		}
		current = valueNode
		if idxStr != "" {
			idx, _ := strconv.Atoi(idxStr)
			if current.Kind != yaml.SequenceNode {
				return "null", true, nil
			}
			if idx < 0 || idx >= len(current.Content) {
				return "null", true, nil
			}
			current = current.Content[idx]
		}
	}
	return convertOutputNode(cfg, current)
}

func evaluateAssignment(cfg Config, expr string, docContent string) (string, bool, error) {
	// Split on " = " (first occurrence)
	// Supports ".a = 2", ".a.b = \"hello\"", ".a = strenv(VAR)" etc
	parts := strings.SplitN(expr, "=", 2)
	if len(parts) != 2 {
		return "", false, fmt.Errorf("invalid assignment")
	}
	lhs := strings.TrimSpace(parts[0])
	rhs := strings.TrimSpace(parts[1])
	// Remove "|=" vs "="? Handle "|=" as update assignment, but treat as =
	if strings.HasSuffix(lhs, "|") {
		lhs = strings.TrimSuffix(lhs, "|")
		lhs = strings.TrimSpace(lhs)
	}
	// lhs should be simple path
	if !isSimplePath(lhs) {
		// fallback to jq
		return "", false, fmt.Errorf("fallback")
	}
	// rhs value: could be string literal, number, bool, null, or strenv, or path?
	// For now handle literals and strenv and simple paths
	var rhsNode yaml.Node
	rhsTrim := strings.TrimSpace(rhs)
	// Check for quoted string
	if (strings.HasPrefix(rhsTrim, `"`) && strings.HasSuffix(rhsTrim, `"`)) || (strings.HasPrefix(rhsTrim, `'`) && strings.HasSuffix(rhsTrim, `'`)) {
		val := strings.Trim(rhsTrim, `"`)
		val = strings.Trim(val, `'`)
		// handle escaped?
		rhsNode.Kind = yaml.ScalarNode
		rhsNode.Tag = "!!str"
		rhsNode.Value = val
		// preserve quotes? original's assignment with "cool" results in a: cool (unquoted) or "cool" depends on output
		// For simplicity use plain
		rhsNode.Style = 0
	} else if rhsTrim == "true" || rhsTrim == "false" {
		rhsNode.Kind = yaml.ScalarNode
		rhsNode.Tag = "!!bool"
		rhsNode.Value = rhsTrim
	} else if rhsTrim == "null" {
		rhsNode.Kind = yaml.ScalarNode
		rhsNode.Tag = "!!null"
		rhsNode.Value = "null"
	} else if rhsTrim == "[]" || rhsTrim == "{}" {
		// empty array/map
		if rhsTrim == "[]" {
			rhsNode.Kind = yaml.SequenceNode
			rhsNode.Tag = "!!seq"
			rhsNode.Style = yaml.FlowStyle
		} else {
			rhsNode.Kind = yaml.MappingNode
			rhsNode.Tag = "!!map"
			rhsNode.Style = yaml.FlowStyle
		}
	} else if strings.HasPrefix(rhsTrim, "strenv(") {
		if cfg.SecurityDisableEnvOps {
			return "", false, fmt.Errorf("env operations have been disabled")
		}
		re := regexp.MustCompile(`strenv\(([^)]+)\)`)
		m := re.FindStringSubmatch(rhsTrim)
		if len(m) > 1 {
			varName := strings.TrimSpace(m[1])
			varName = strings.Trim(varName, `"`)
			varName = strings.Trim(varName, `'`)
			val := os.Getenv(varName)
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!str"
			rhsNode.Value = val
		}
	} else if strings.HasPrefix(rhsTrim, "env(") {
		if cfg.SecurityDisableEnvOps {
			return "", false, fmt.Errorf("env operations have been disabled")
		}
		re := regexp.MustCompile(`env\(([^)]+)\)`)
		m := re.FindStringSubmatch(rhsTrim)
		if len(m) > 1 {
			varName := strings.TrimSpace(m[1])
			varName = strings.Trim(varName, `"`)
			varName = strings.Trim(varName, `'`)
			val := os.Getenv(varName)
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!str"
			rhsNode.Value = val
		}
	} else if isSimplePath(rhsTrim) {
		// rhs is path like .b.c ; need to fetch value from doc
		// For now fallback to jq for complex
		return "", false, fmt.Errorf("fallback to jq")
	} else {
		// Try to parse as number
		if _, err := strconv.Atoi(rhsTrim); err == nil {
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!int"
			rhsNode.Value = rhsTrim
		} else if _, err := strconv.ParseFloat(rhsTrim, 64); err == nil {
			rhsNode.Kind = yaml.ScalarNode
			rhsNode.Tag = "!!float"
			rhsNode.Value = rhsTrim
		} else {
			// fallback
			return "", false, fmt.Errorf("fallback")
		}
	}

	// Now we have doc to modify
	var docNode yaml.Node
	if err := yaml.Unmarshal([]byte(docContent), &docNode); err != nil {
		// if empty, create new document
		docNode.Kind = yaml.DocumentNode
		var mapNode yaml.Node
		mapNode.Kind = yaml.MappingNode
		mapNode.Tag = "!!map"
		docNode.Content = []*yaml.Node{&mapNode}
	}
	if len(docNode.Content) == 0 {
		var mapNode yaml.Node
		mapNode.Kind = yaml.MappingNode
		mapNode.Tag = "!!map"
		docNode.Content = []*yaml.Node{&mapNode}
	}
	target := docNode.Content[0]
	// If target is not mapping (e.g., scalar), need to replace?
	// For assignment .a = 2 on empty or null, create mapping

	// Traverse lhs path, creating intermediate nodes if needed
	path := strings.TrimPrefix(lhs, ".")
	parts := strings.Split(path, ".")
	current := target
	for i, part := range parts {
		re := regexp.MustCompile(`^(\w+)(?:\[(\d+)\])?$`)
		m := re.FindStringSubmatch(part)
		if m == nil {
			return "", false, fmt.Errorf("invalid path")
		}
		key := m[1]
		idxStr := m[2]
		isLast := i == len(parts)-1

		if current.Kind != yaml.MappingNode {
			// cannot create field on non-map, replace with map?
			// For simplicity, error
			return "", false, fmt.Errorf("cannot assign to non-map")
		}
		// Find key
		var foundIdx int = -1
		var valueNode *yaml.Node
		for idx := 0; idx < len(current.Content); idx += 2 {
			k := current.Content[idx]
			if k.Value == key {
				foundIdx = idx
				valueNode = current.Content[idx+1]
				break
			}
		}
		if isLast {
			if idxStr != "" {
				// assigning to array element: .a[0] = 2
				if foundIdx == -1 {
					// create array
					var seq yaml.Node
					seq.Kind = yaml.SequenceNode
					seq.Tag = "!!seq"
					// need to fill up to idx?
					idx, _ := strconv.Atoi(idxStr)
					// fill with nulls
					for j := 0; j <= idx; j++ {
						var nullNode yaml.Node
						nullNode.Kind = yaml.ScalarNode
						nullNode.Tag = "!!null"
						nullNode.Value = "null"
						if j == idx {
							nullNode = rhsNode
						}
						seq.Content = append(seq.Content, &nullNode)
					}
					// append to map
					var keyNode yaml.Node
					keyNode.Kind = yaml.ScalarNode
					keyNode.Tag = "!!str"
					keyNode.Value = key
					current.Content = append(current.Content, &keyNode, &seq)
				} else {
					// existing array, set element
					if valueNode.Kind != yaml.SequenceNode {
						return "", false, fmt.Errorf("not an array")
					}
					idx, _ := strconv.Atoi(idxStr)
					// expand if needed
					for len(valueNode.Content) <= idx {
						var nullNode yaml.Node
						nullNode.Kind = yaml.ScalarNode
						nullNode.Tag = "!!null"
						nullNode.Value = "null"
						valueNode.Content = append(valueNode.Content, &nullNode)
					}
					// replace
					// Need to allocate new node to avoid reference issues
					newNode := rhsNode
					valueNode.Content[idx] = &newNode
				}
			} else {
				if foundIdx == -1 {
					var keyNode yaml.Node
					keyNode.Kind = yaml.ScalarNode
					keyNode.Tag = "!!str"
					keyNode.Value = key
					// need to copy rhsNode
					newNode := rhsNode
					current.Content = append(current.Content, &keyNode, &newNode)
				} else {
					newNode := rhsNode
					current.Content[foundIdx+1] = &newNode
				}
			}
		} else {
			// intermediate node, need to traverse/create
			if foundIdx == -1 {
				// create new mapping
				var newMap yaml.Node
				newMap.Kind = yaml.MappingNode
				newMap.Tag = "!!map"
				var keyNode yaml.Node
				keyNode.Kind = yaml.ScalarNode
				keyNode.Tag = "!!str"
				keyNode.Value = key
				current.Content = append(current.Content, &keyNode, &newMap)
				current = &newMap
				// Note: we added to current.Content but current is pointer to original mapping's content; need to update reference
				// Actually we appended to current.Content slice, but current points to target's content mapping; after append, we need to find the newly added map
				// Since we just created newMap as value, we should set current to that map we can retrieve
				// Find last value
				current = current.Content[len(current.Content)-1]
			} else {
				// need to handle idxStr for intermediate array? e.g., .a[0].b
				if idxStr != "" {
					idx, _ := strconv.Atoi(idxStr)
					if valueNode.Kind != yaml.SequenceNode {
						return "", false, fmt.Errorf("not an array")
					}
					if idx >= len(valueNode.Content) {
						// create missing entries as maps?
						for len(valueNode.Content) <= idx {
							var newMap yaml.Node
							newMap.Kind = yaml.MappingNode
							newMap.Tag = "!!map"
							valueNode.Content = append(valueNode.Content, &newMap)
						}
					}
					current = valueNode.Content[idx]
					if current.Kind != yaml.MappingNode {
						// Convert scalar to mapping? For now error
					}
				} else {
					current = valueNode
					if current.Kind != yaml.MappingNode {
						// if intermediate is scalar, need to replace with map? But assignment would overwrite
						// Create new map and replace?
						var newMap yaml.Node
						newMap.Kind = yaml.MappingNode
						newMap.Tag = "!!map"
						current.Content = newMap.Content
						current.Kind = newMap.Kind
						current.Tag = newMap.Tag
					}
				}
			}
		}
	}
	// Encode back to yaml
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.Indent)
	if err := enc.Encode(&docNode); err != nil {
		return "", false, err
	}
	enc.Close()
	out := buf.String()
	// handle prettyPrint? For assignment, style already set, but prettyPrint clears style
	if cfg.PrettyPrint {
		out = prettyPrintYaml(out)
	}
	if cfg.YamlCompactSeqIndent {
		out = compactSeqIndent(out)
	}
	// For output format json, convert
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		var v interface{}
		yaml.Unmarshal([]byte(out), &v)
		v = normalizeYaml(v)
		b, _ := json.MarshalIndent(v, "", strings.Repeat(" ", cfg.Indent))
		out = string(b) + "\n"
	}
	// Handle unwrapScalar? For assignment, result is not scalar unwrap
	return strings.TrimSpace(out), false, nil
}

func convertOutput(cfg Config, docContent string, docInfo Doc) (string, bool, error) {
	// Convert docContent to output format with config
	// Handles input format vs output format
	// Simplify: assume yaml input already, output yaml/json etc
	input := strings.TrimSpace(docContent)
	if input == "" {
		return "null", true, nil
	}
	// Check input format
	if cfg.InputFormat == "json" || cfg.InputFormat == "j" {
		// input is json, but docContent is json string
		// Convert to output
		if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
			// pretty print json with indent
			var v interface{}
			json.Unmarshal([]byte(input), &v)
			b, _ := json.MarshalIndent(v, "", strings.Repeat(" ", cfg.Indent))
			return string(b), false, nil
		} else {
			// json to yaml
			var v interface{}
			json.Unmarshal([]byte(input), &v)
			var buf bytes.Buffer
			enc := yaml.NewEncoder(&buf)
			enc.SetIndent(cfg.Indent)
			enc.Encode(v)
			out := buf.String()
			if cfg.PrettyPrint {
				out = prettyPrintYaml(out)
			}
			return strings.TrimSpace(out), false, nil
		}
	}
	// default yaml input
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		var v interface{}
		if err := yaml.Unmarshal([]byte(input), &v); err != nil {
			return "", false, err
		}
		v = normalizeYaml(v)
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetIndent("", strings.Repeat(" ", cfg.Indent))
		enc.SetEscapeHTML(false)
		enc.Encode(v)
		return strings.TrimSpace(buf.String()), false, nil
	} else if cfg.OutputFormat == "props" || cfg.OutputFormat == "p" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toProps(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "csv" || cfg.OutputFormat == "c" {
		return "", false, fmt.Errorf("csv encoding only works for arrays, got: !!map")
		// Actually need to check v type
	} else if cfg.OutputFormat == "xml" || cfg.OutputFormat == "x" {
		// xml output: wrap?
		// Simplified: output as <a>...</a>
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toXml(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "shell" || cfg.OutputFormat == "s" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toShell(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "lua" || cfg.OutputFormat == "l" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toLua(v, cfg)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "ini" || cfg.OutputFormat == "i" {
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		out := toIni(v)
		return strings.TrimSpace(out), false, nil
	} else if cfg.OutputFormat == "base64" {
		return "", false, fmt.Errorf("cannot encode !!map as base64, can only operate on strings")
	} else if cfg.OutputFormat == "uri" {
		return "", false, fmt.Errorf("cannot encode !!map as URI, can only operate on strings. Please first pipe through another encoding operator to convert the value to a string")
	} else if cfg.OutputFormat == "toml" {
		// stub
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		v = normalizeYaml(v)
		b, _ := json.Marshal(v)
		var m map[string]interface{}
		json.Unmarshal(b, &m)
		var sb strings.Builder
		for k, val := range m {
			switch vt := val.(type) {
			case string:
				sb.WriteString(fmt.Sprintf("%s = \"%s\"\n", k, vt))
			default:
				sb.WriteString(fmt.Sprintf("%s = %v\n", k, vt))
			}
		}
		return strings.TrimSpace(sb.String()), false, nil
	}
	// default yaml output
	// Need to handle yaml style, prettyPrint, etc
	var node yaml.Node
	if err := yaml.Unmarshal([]byte(input), &node); err != nil {
		// try to re-encode via generic if node fails?
		var v interface{}
		yaml.Unmarshal([]byte(input), &v)
		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(cfg.Indent)
		enc.Encode(v)
		out := buf.String()
		if cfg.PrettyPrint {
			out = prettyPrintYaml(out)
		}
		return strings.TrimSpace(out), false, nil
	}
	if len(node.Content) == 0 {
		return "", false, nil
	}
	docNode := node.Content[0]
	// Handle output format auto: already yaml
	// But need to handle indent, pretty, no-doc, etc at higher level, here just convert node to string with indent
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.Indent)
	enc.Encode(docNode)
	out := buf.String()
	// enc.Encode adds "---" for multi? For single doc, it adds no "---"? Actually it adds newline
	// Remove trailing newline trim handled by caller
	if cfg.PrettyPrint {
		out = prettyPrintYaml(out)
	}
	if cfg.YamlCompactSeqIndent {
		out = compactSeqIndent(out)
	}
	// For yaml output, unwrap handling already? For simple path we did, but here identity returns whole doc without unwrap
	return strings.TrimSpace(out), false, nil
}

func convertOutputNode(cfg Config, node *yaml.Node) (string, bool, error) {
	// Node is yaml.Node to output
	// Check if it's scalar and unwrap
	if node.Kind == yaml.ScalarNode {
		if cfg.NulOutput && strings.Contains(node.Value, "\x00") {
			return "", false, fmt.Errorf("nul output with NUL in scalar")
		}
		if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
			// json output for scalar
			var v interface{}
			// Use tag to determine type
			switch node.Tag {
			case "!!int":
				i, _ := strconv.Atoi(node.Value)
				v = i
			case "!!bool":
				v = node.Value == "true"
			case "!!null":
				v = nil
			default:
				v = node.Value
			}
			b, _ := json.Marshal(v)
			// json marshaling for string adds quotes, but unwrap for json? json always quoted for string, not unwrap?
			// For json output, unwrap not applicable? Original with -o json and scalar would output json scalar with quotes? Check: echo 'a: hello' | yq -o json '.a' => "hello" (quoted) not hello
			// So for json output, even if unwrap true, we should output json string with quotes
			if s, ok := v.(string); ok && cfg.OutputFormat != "json" && cfg.OutputFormat != "j" {
				// not json, unwrap
				if cfg.UnwrapScalar {
					return s, false, nil
				}
				return fmt.Sprintf("%q", s), false, nil
			}
			// For json, b already is quoted
			return string(b), false, nil
		}
		// yaml output with unwrap
		if cfg.UnwrapScalar {
			// check tag for null/false for exit-status?
			if node.Tag == "!!null" {
				return "null", true, nil
			}
			if node.Tag == "!!bool" && node.Value == "false" {
				return "false", true, nil
			}
			return node.Value, false, nil
		} else {
			// Need to output with quotes if needed
			// Determine if string needs quoting: if tag is !!str and style was plain? But we lost style, now node.Style indicates original style
			// For scalar not unwrapped, we should output with appropriate style: if original was double quoted, output double quoted
			// Our node.Style holds original style (0 plain, 2 double, 4 single etc)
			// For unwrap false, we should output with quotes if style indicates string
			var buf bytes.Buffer
			enc := yaml.NewEncoder(&buf)
			enc.SetIndent(cfg.Indent)
			// Create doc node
			var doc yaml.Node
			doc.Kind = yaml.DocumentNode
			doc.Content = []*yaml.Node{node}
			enc.Encode(&doc)
			out := strings.TrimSpace(buf.String())
			if out == "" {
				out = node.Value
			}
			// check null
			if node.Tag == "!!null" {
				return "null", true, nil
			}
			if node.Tag == "!!bool" && node.Value == "false" {
				return "false", true, nil
			}
			return out, false, nil
		}
	}
	// For non-scalar (map, seq), encode as yaml/json etc
	if cfg.OutputFormat == "json" || cfg.OutputFormat == "j" {
		// Convert node to generic then to json
		var v interface{}
		// Decode node to generic
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetIndent("", strings.Repeat(" ", cfg.Indent))
		enc.SetEscapeHTML(false)
		enc.Encode(v)
		return strings.TrimSpace(buf.String()), false, nil
	}
	if cfg.OutputFormat == "props" || cfg.OutputFormat == "p" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		out := toProps(v, cfg)
		return strings.TrimSpace(out), false, nil
	}
	if cfg.OutputFormat == "xml" || cfg.OutputFormat == "x" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toXml(v, cfg)), false, nil
	}
	if cfg.OutputFormat == "shell" || cfg.OutputFormat == "s" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toShell(v, cfg)), false, nil
	}
	if cfg.OutputFormat == "lua" || cfg.OutputFormat == "l" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toLua(v, cfg)), false, nil
	}
	if cfg.OutputFormat == "ini" || cfg.OutputFormat == "i" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		return strings.TrimSpace(toIni(v)), false, nil
	}
	if cfg.OutputFormat == "csv" || cfg.OutputFormat == "c" {
		var v interface{}
		b, _ := yaml.Marshal(node)
		yaml.Unmarshal(b, &v)
		v = normalizeYaml(v)
		// check if array
		if arr, ok := v.([]interface{}); ok {
			return toCsv(arr, cfg), false, nil
		}
		return "", false, fmt.Errorf("csv encoding only works for arrays, got: %s", node.Tag)
	}
	if cfg.OutputFormat == "base64" {
		if node.Kind == yaml.ScalarNode && node.Tag == "!!str" {
			enc := strings.TrimSpace(node.Value)
			// base64 encode
			var out string
