func compactSeqIndent(yamlStr string) string {
	// Replace "  - " with "- " and handle indent?
	lines := strings.Split(yamlStr, "\n")
	for i, line := range lines {
		// count leading spaces
		trimmed := strings.TrimLeft(line, " ")
		indent := len(line) - len(trimmed)
		if strings.HasPrefix(trimmed, "- ") && indent >= 2 {
			// compact: indent = indent -2 ??? Actually original -c makes '- ' part of indentation
			// Example: a:\n  - 1 -> a:\n- 1 ? No, original showed a:\n- 1\n- 2 (no indent for seq items)
			// So we reduce indent by 2 for lines starting with "-"
			newIndent := indent - 2
			if newIndent < 0 {
				newIndent = 0
			}
			lines[i] = strings.Repeat(" ", newIndent) + trimmed
		}
	}
	return strings.Join(lines, "\n")
}

