		cmd := exec.Command("jq", "-n", "--argjson", "index", fmt.Sprintf("%d", index), splitExp)
		var out bytes.Buffer
		var errBuf bytes.Buffer
		cmd.Stdout = &out
		cmd.Stderr = &errBuf
		if err := cmd.Run(); err == nil {
			res := strings.TrimSpace(out.String())
			// jq outputs json string with quotes
			res = strings.Trim(res, `"`)
			if res != "" {
				return res
			}
		}
		// fallback: replace $index string
		return strings.ReplaceAll(splitExp, "$index", fmt.Sprintf("%d", index))
	}
	s := strings.Trim(splitExp, `"`)
	s = strings.Trim(s, `'`)
	s = strings.ReplaceAll(s, "$index", fmt.Sprintf("%d", index))
	return s
}

func printNodeInfo(node *yaml.Node, depth int) {
	indent := strings.Repeat("  ", depth)
	if node.Kind == yaml.DocumentNode {
		for _, c := range node.Content {
			printNodeInfo(c, depth)
		}
		return
	}
	kindStr := ""
	switch node.Kind {
	case yaml.MappingNode:
		kindStr = "MappingNode"
	case yaml.SequenceNode:
		kindStr = "SequenceNode"
	case yaml.ScalarNode:
		kindStr = "ScalarNode"
	case yaml.AliasNode:
		kindStr = "AliasNode"
	}
	fmt.Printf("%skind: %s\n", indent, kindStr)
	fmt.Printf("%stag: '%s'\n", indent, node.Tag)
	if node.Kind == yaml.ScalarNode {
		fmt.Printf("%svalue: %q\n", indent, node.Value)
	}
	fmt.Printf("%sline: 1\n", indent)
	fmt.Printf("%scolumn: 1\n", indent)
	if len(node.Content) > 0 {
		fmt.Printf("%scontent:\n", indent)
		for _, c := range node.Content {
			printNodeInfo(c, depth+1)
		}
	}
}
